----------------------------------------------------------------------
-- 5. Courses
----------------------------------------------------------------------
INSERT INTO courses (
  id, title, short_description, long_description, grade, term, subject,
  school_id, teacher_id, department_id, retakeable, prereq_options,
  coreq_options, max_student_count, term_options
) VALUES

('b9c16ab2-8035-4b11-8e1b-9ab74d84f799', 'Mathematics Research Seminar', 'Covers independent conjecture, literature review, proof, and exposition.', 'The term opens with concrete problems tied to independent conjecture, literature review, proof, and exposition, then widens toward independent work. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. By the end, students should explain key ideas in independent conjecture, literature review, proof, and exposition clearly and apply them without a scripted worksheet.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'd162cc07-ed4d-462c-ab42-91ec8890fd8c', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 12, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('aeb1e35a-4645-43c2-a61c-b8f984a5cac6', 'Integrated Math I', 'A practical look at an integrated foundation in algebra, geometry, and data.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into an integrated foundation in algebra, geometry, and data, others synthesize. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about an integrated foundation in algebra, geometry, and data under modest time pressure.', ARRAY[9], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'cdc3f7d2-dd34-4566-b55c-b74fff61a3d9', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('f2fa7e69-e01c-4aca-8749-499d873046f7', 'Trigonometry', 'A practical look at circular functions, identities, and triangle applications.', 'Materials range from classic sources to current tools, all oriented around circular functions, identities, and triangle applications. The teacher conferences mid-term to adjust challenge level without watering down standards.', ARRAY[10,11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '581a27c8-67b8-42f7-b8af-7fc996099248', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('d0d77e92-bd6f-4f31-abf5-4afa5aee2d0f', 'Honors Algebra I', 'Accelerated algebraic reasoning and multi-step function problems.', 'Students who enroll should be ready for sustained attention to accelerated algebraic reasoning and multi-step function problems and for revising unfinished work. Support structures include office hours, peer tutors, and optional extension problems for those who want more. A final project or exam asks students to integrate what they learned about accelerated algebraic reasoning and multi-step function problems under modest time pressure.', ARRAY[9], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'f5f756f5-51e6-40f9-8716-ab6a31355d81', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe', 'Algebra I', 'Linear equations, functions, and algebraic modeling.', 'Field-adjacent examples keep linear equations, functions, and algebraic modeling connected to situations students recognize outside school. Support structures include office hours, peer tutors, and optional extension problems for those who want more. By the end, students should explain key ideas in linear equations, functions, and algebraic modeling clearly and apply them without a scripted worksheet.', ARRAY[9], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'afd855ce-bf6f-462e-9136-183e6b00d9a9', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('387fc358-6429-4a36-8c3c-7d6b3aec104c', 'Probability and Statistics', 'Applied study of random variables, simulation, distributions, and inference.', 'Graphing tools and written justification are both expected when students present work on random variables, simulation, distributions, and inference. Support structures include office hours, peer tutors, and optional extension problems for those who want more. By the end, students should explain key ideas in random variables, simulation, distributions, and inference clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '933730a8-8aec-4a5b-b7a6-5917f1d0697d', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9296d7bc-56b2-408b-974a-ec480bd567eb', 'Precalculus with Trigonometry', 'Lab- and project-driven work on function analysis reinforced by sustained trigonometric practice.', 'Graphing tools and written justification are both expected when students present work on function analysis reinforced by sustained trigonometric practice. The teacher conferences mid-term to adjust challenge level without watering down standards. By the end, students should explain key ideas in function analysis reinforced by sustained trigonometric practice clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'b08f072d-7fac-4d7c-a8ec-e8095dc0856c', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('77d55b3c-ce53-4c5d-9968-9afb64c32502', 'Discrete Mathematics', 'Hands-on experience with combinatorics, graph theory, logic, and recurrence.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into combinatorics, graph theory, logic, and recurrence, others synthesize. Group roles rotate so no one is permanently the scribe or the spokesperson. By the end, students should explain key ideas in combinatorics, graph theory, logic, and recurrence clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'cc426faf-5738-4297-a7c5-aa0e10f1e4a3', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Placement test']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('ba33aea6-ccf5-40ad-9ecc-8fd25e4ebc9d', 'Integrated Math II', 'Lab- and project-driven work on quadratics, similarity, right-triangle trigonometry, and probability.', 'Early assessments check fluency; later ones ask students to combine ideas related to quadratics, similarity, right-triangle trigonometry, and probability. Group roles rotate so no one is permanently the scribe or the spokesperson. Later courses in the department will assume familiarity with quadratics, similarity, right-triangle trigonometry, and probability.', ARRAY[10], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '01e28ecf-f26f-44c1-81f6-162b09fee7e5', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('055faed0-cb08-419a-9e79-483f61728b76', 'Geometry and Construction', 'Compass-and-straightedge constructions supported by proof.', 'Rather than racing through a checklist, the class returns repeatedly to compass-and-straightedge constructions supported by proof until ideas feel usable. Students annotate their own errors and resubmit selected pieces after feedback. By the end, students should explain key ideas in compass-and-straightedge constructions supported by proof clearly and apply them without a scripted worksheet.', ARRAY[10,11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'a3ad5bf1-2d66-457f-bcb0-0730fa9c07f6', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('a8978b6e-9f2b-4864-9453-a035b3515eff', 'Exponential and Logarithmic Functions', 'Term work on growth, decay, logarithmic equations, and applied models.', 'Graphing tools and written justification are both expected when students present work on growth, decay, logarithmic equations, and applied models. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '9fa907ef-1262-4dce-9cf6-3d9fc559e475', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('867bf181-95a6-4631-b5bf-02e3caa81641', 'College Algebra', 'Covers college-paced polynomial, rational, exponential, and logarithmic functions.', 'The term opens with concrete problems tied to college-paced polynomial, rational, exponential, and logarithmic functions, then widens toward independent work. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. By the end, students should explain key ideas in college-paced polynomial, rational, exponential, and logarithmic functions clearly and apply them without a scripted worksheet.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'de8a91af-a2cc-4440-9804-eb780cf29a15', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 30, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('b2f5a1dd-cb9f-4a6b-bed7-1239dbce2c54', 'Calculus I', 'A practical look at college-level limits, derivatives, optimization, and curve analysis.', 'Materials range from classic sources to current tools, all oriented around college-level limits, derivatives, optimization, and curve analysis. Students annotate their own errors and resubmit selected pieces after feedback. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'c7b76232-10ed-4cb2-b1c2-bc01ab4d65b5', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('88782c80-d609-406b-a755-344936ac3332', 'Number Theory', 'Term work on primes, divisibility, modular arithmetic, and cryptography.', 'Expect a mix of short drills and longer investigations organized around primes, divisibility, modular arithmetic, and cryptography. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in primes, divisibility, modular arithmetic, and cryptography clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'a1cc2085-4740-45eb-8525-40be3d6c903d', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Placement test']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('7e3d9b97-d699-4eb6-a0f7-7b570f6b2f8e', 'Pre-Calculus', 'An elective built around advanced functions, trigonometry, and analytic geometry.', 'Students who enroll should be ready for sustained attention to advanced functions, trigonometry, and analytic geometry and for revising unfinished work. Students annotate their own errors and resubmit selected pieces after feedback. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '87764a68-32e8-47fa-b7c6-5a2da7a12816', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe','a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('eb39c60b-c228-4248-b890-4b39b7b2c241', 'Honors Pre-Calculus', 'Skills and concepts in intensive trigonometry, vectors, sequences, and limits.', 'Problem sets reward multiple solution paths, especially when wrestling with intensive trigonometry, vectors, sequences, and limits. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about intensive trigonometry, vectors, sequences, and limits under modest time pressure.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '14483524-3215-4978-af21-24cf4b57a787', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('87e0ec54-1618-4fc6-bf2a-52b2a39bf77a', 'Mathematical Logic', 'A practical look at propositions, predicates, quantifiers, and proof structures.', 'Early assessments check fluency; later ones ask students to combine ideas related to propositions, predicates, quantifiers, and proof structures. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '98794a33-0c32-4de0-be8d-4fa31ef5d873', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('0e25c31a-f393-42a3-92e0-8766a8f099c7', 'Integrated Math III', 'Applied study of polynomial functions, trigonometry, and statistical reasoning.', 'The term opens with concrete problems tied to polynomial functions, trigonometry, and statistical reasoning, then widens toward independent work. Group roles rotate so no one is permanently the scribe or the spokesperson. Later courses in the department will assume familiarity with polynomial functions, trigonometry, and statistical reasoning.', ARRAY[11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'cde19536-3e5c-44d6-9167-4895dcdaf764', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('d548ad94-dea2-42a3-821f-77dfe3db65b9', 'Competition Math', 'Creative contest strategies across algebra, geometry, and counting.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how creative contest strategies across algebra, geometry, and counting is used. Students leave with notes and graded work that document progress on creative contest strategies across algebra, geometry, and counting.', ARRAY[9,10,11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '9d460288-e1fc-4e45-ac82-419712b117ed', 'a2b22222-0000-4000-a000-000000000001', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('591b81e7-8336-4dd9-94bf-0f24ecae9944', 'Advanced Problem Solving', 'Practice with olympiad-style reasoning, elegant proofs, and solution critique.', 'Workshops, mini-lectures, and critiques rotate so that olympiad-style reasoning, elegant proofs, and solution critique never stays only on a worksheet. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A final project or exam asks students to integrate what they learned about olympiad-style reasoning, elegant proofs, and solution critique under modest time pressure.', ARRAY[10,11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '73a51b8f-f6ce-4795-9fb2-be84ee95a696', 'a2b22222-0000-4000-a000-000000000001', true, ARRAY[ARRAY['Instructor permission']], NULL, 12, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('48b39fa4-21f9-42c8-aa2a-acdb2a528414', 'AP Statistics', 'Covers data analysis, experimental design, probability, and inference.', 'This offering is sequenced for the grades it serves, with data analysis, experimental design, probability, and inference as the spine of major assignments. A final project or exam asks students to integrate what they learned about data analysis, experimental design, probability, and inference under modest time pressure.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '1d584390-d547-480f-a0bd-6552be35c0e3', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('a6deaa5d-2206-478b-9d00-4145922d4bb9', 'Real Analysis Seminar', 'Hands-on experience with rigorous limits, continuity, convergence, and epsilon-delta reasoning.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into rigorous limits, continuity, convergence, and epsilon-delta reasoning, others synthesize. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '8d23b8c4-eb54-45a5-b07c-8d9e79348ebc', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e','a9541047-4970-45a2-a979-70d58f9b8909'], ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075','']], NULL, 12, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('925bb5d2-cd84-4c32-a2cc-4941d4519b1a', 'Honors Geometry', 'For students ready to take on rigorous proof writing, constructions, and geometric transformations.', 'Students who enroll should be ready for sustained attention to rigorous proof writing, constructions, and geometric transformations and for revising unfinished work. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about rigorous proof writing, constructions, and geometric transformations under modest time pressure.', ARRAY[9,10], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'fe11237b-fd1c-48c9-ad1f-87d44ae1c267', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9ee3a7de-1986-428f-a0cf-cdbaac47af8b', 'Matrix Algebra', 'For students ready to take on row reduction, matrix operations, systems, and transformations.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how row reduction, matrix operations, systems, and transformations is used. Students annotate their own errors and resubmit selected pieces after feedback. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '3b256251-32be-4d16-9983-85635fc45541', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('a9541047-4970-45a2-a979-70d58f9b8909', 'Geometry', 'Term work on deductive proof, spatial reasoning, and geometric measurement.', 'Expect a mix of short drills and longer investigations organized around deductive proof, spatial reasoning, and geometric measurement. Students leave with notes and graded work that document progress on deductive proof, spatial reasoning, and geometric measurement.', ARRAY[9,10], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'f9d10a6f-670a-4d22-8312-053c92dffc61', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('c03e27ad-a7a6-47e1-b2a4-1b0a2c444ecc', 'Math for Data Science', 'Hands-on experience with vectors, matrices, regression, and computational data analysis.', 'The term opens with concrete problems tied to vectors, matrices, regression, and computational data analysis, then widens toward independent work. Support structures include office hours, peer tutors, and optional extension problems for those who want more.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '7ac9ae21-97cd-47ff-9da0-75749a6a0091', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('738204e7-acc4-41e6-988a-c861e4cf9669', 'Topology for Explorers', 'Surfaces, continuity, invariants, and rubber-sheet geometry.', 'Rather than racing through a checklist, the class returns repeatedly to surfaces, continuity, invariants, and rubber-sheet geometry until ideas feel usable. Support structures include office hours, peer tutors, and optional extension problems for those who want more.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'c10a917e-df6a-4dfb-afb1-17ac4d09fae7', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('78807ae8-a121-4e41-b22d-cfc5b50c7337', 'Game Theory', 'A practical look at payoff matrices, strategic behavior, and equilibrium.', 'This offering is sequenced for the grades it serves, with payoff matrices, strategic behavior, and equilibrium as the spine of major assignments. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Later courses in the department will assume familiarity with payoff matrices, strategic behavior, and equilibrium.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '8212b2e5-aaf4-4386-a023-689f98939904', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('0ca39c77-4966-4e9f-85ce-35d2b39e132a', 'Applied Calculus', 'Rates of change and accumulation in business and life sciences.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how rates of change and accumulation in business and life sciences is used. Group roles rotate so no one is permanently the scribe or the spokesperson. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '69e1eb2f-e597-4044-a115-4e33287d68b2', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('79d120a3-cdea-4852-9b0e-28d87ddb843f', 'Honors Algebra II', 'Hands-on experience with complex numbers, rational functions, and advanced modeling.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into complex numbers, rational functions, and advanced modeling, others synthesize. Later courses in the department will assume familiarity with complex numbers, rational functions, and advanced modeling.', ARRAY[10,11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '0cba6300-b08a-42b4-98ba-e565982bd372', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('7c9c7e1a-3c05-42af-ae46-261c10399737', 'History of Mathematics', 'The development of mathematical notation, proof, and major ideas.', 'Students who enroll should be ready for sustained attention to the development of mathematical notation, proof, and major ideas and for revising unfinished work. Reading loads stay manageable; the heavier lift is interpreting and producing original work. By the end, students should explain key ideas in the development of mathematical notation, proof, and major ideas clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'f031a765-9871-4f76-b01a-363206557881', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('687c9cf9-308c-4bf3-a09c-ba962e12f6cb', 'Financial Mathematics', 'Attention to interest, annuities, amortization, risk, and investment.', 'Teachers model professional habits while students pursue interest, annuities, amortization, risk, and investment in pairs and on their own. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. Later courses in the department will assume familiarity with interest, annuities, amortization, risk, and investment.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'c7f2e22d-78f0-4a06-98ab-d66039f0d73a', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('772e8813-5366-4951-b997-8c5dc33a7f7a', 'Math Analysis', 'Hands-on experience with function behavior, inverse relationships, sequences, and limits.', 'Graphing tools and written justification are both expected when students present work on function behavior, inverse relationships, sequences, and limits. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Later courses in the department will assume familiarity with function behavior, inverse relationships, sequences, and limits.', ARRAY[11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '2b42cb58-d6d9-4db5-ab98-ed4c63d3157e', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('68d2cda2-a0c1-462e-acea-234fca6dedca', 'Linear Algebra', 'Applied study of matrices, vector spaces, transformations, and eigenvalues.', 'This offering is sequenced for the grades it serves, with matrices, vector spaces, transformations, and eigenvalues as the spine of major assignments. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students leave with notes and graded work that document progress on matrices, vector spaces, transformations, and eigenvalues.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '0a5c88dd-37dd-4b09-8c8c-c096f4610a7e', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('4d5130c4-e18b-4ce3-a7ba-88620068cd4f', 'Statistics', 'Core work includes descriptive statistics, regression, probability, and basic inference.', 'Students spend most of class deeply engaged with descriptive statistics, regression, probability, and basic inference, moving between explanation, practice, and critique. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'e63aabbd-8de9-4582-9016-b89ec4dbd17e', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9352533d-9b5c-49ea-8426-6d64b653827e', 'Algebra II', 'Covers quadratics, polynomials, exponentials, and logarithms.', 'Early assessments check fluency; later ones ask students to combine ideas related to quadratics, polynomials, exponentials, and logarithms. Students annotate their own errors and resubmit selected pieces after feedback. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'cdc7480b-d183-4854-9849-f606b373ac68', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 27, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('6fda88bd-1f31-4c00-b01d-56a0220f507f', 'Combinatorics', 'Emphasis on advanced counting, inclusion-exclusion, and generating functions.', 'The term opens with concrete problems tied to advanced counting, inclusion-exclusion, and generating functions, then widens toward independent work. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '6f112b74-c53a-46d9-8a56-092dff448f48', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('b98d1e11-081a-4919-a75d-add4adeb05f9', 'AP Calculus BC', 'For students ready to take on series, parametric curves, polar coordinates, and vector functions.', 'Discussion norms matter here: peers must press on each other''s reasoning about series, parametric curves, polar coordinates, and vector functions. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '33807ce1-4015-442a-aa1b-1bf3f721b369', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e','a9541047-4970-45a2-a979-70d58f9b8909'], ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075',''], ARRAY['Department approval','']], ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454','f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 18, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('00008e6c-3ee8-48cc-aff6-138d206ef035', 'Calculus II', 'Lab- and project-driven work on integration techniques, volumes, arc length, and sequences.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into integration techniques, volumes, arc length, and sequences, others synthesize. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Later courses in the department will assume familiarity with integration techniques, volumes, arc length, and sequences.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '43ff9c9b-2d4b-420c-9bde-596fbc3f6b6d', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('fdefe41f-5d04-42e7-bf5c-1718b748ff23', 'Finite Mathematics', 'Lab- and project-driven work on linear programming, matrices, Markov chains, and finance.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into linear programming, matrices, Markov chains, and finance, others synthesize. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '12650220-cd02-495d-8684-697447e4e23c', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('f0649d31-a7d4-4b84-a757-4f758674014b', 'Multivariable Calculus', 'Applied study of partial derivatives, multiple integrals, and vector calculus.', 'Capstone planning begins early so students can shape personal angles on partial derivatives, multiple integrals, and vector calculus. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '6adbf85d-6d00-42c9-b2cf-1a8e0e1e8abf', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229'], ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77']], NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('067a8e42-a980-424d-8fdb-4c077a46e312', 'SAT Math Prep', 'Covers timed mathematical reasoning, test strategy, and error analysis.', 'Expect a mix of short drills and longer investigations organized around timed mathematical reasoning, test strategy, and error analysis. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Later courses in the department will assume familiarity with timed mathematical reasoning, test strategy, and error analysis.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'e0504a82-c7ff-46f6-aae9-29edac19d731', 'a2b22222-0000-4000-a000-000000000001', true, NULL, NULL, 32, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('c1a7ce0e-b1e5-41a3-846a-4f4c18842633', 'Graph Theory', 'Applied study of paths, trees, networks, coloring, and graph algorithms.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into paths, trees, networks, coloring, and graph algorithms, others synthesize. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', '1f1235e8-dc51-40c7-b59d-3f92fc951416', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('145ca939-e15b-4795-a7eb-5e341b0df7e5', 'AP Calculus AB', 'For students ready to take on limits, derivatives, integrals, and their applications.', 'Students spend most of class deeply engaged with limits, derivatives, integrals, and their applications, moving between explanation, practice, and critique. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about limits, derivatives, integrals, and their applications under modest time pressure.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'f5653075-f040-4948-a0ea-65e23463cb0a', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe','a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('dbe510ae-df5c-422d-8f26-59ef10bb554e', 'Polynomial Functions', 'Emphasis on factoring, complex roots, end behavior, and graph structure.', 'Graphing tools and written justification are both expected when students present work on factoring, complex roots, end behavior, and graph structure. A final project or exam asks students to integrate what they learned about factoring, complex roots, end behavior, and graph structure under modest time pressure.', ARRAY[10,11], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'fb4ce37e-7171-4726-b0ed-b6ae36cd8942', 'a2b22222-0000-4000-a000-000000000001', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('2d5d792f-abb0-417d-ba00-f04f0f5dc862', 'Quantitative Reasoning', 'Term work on data literacy, risk, voting systems, and fair division.', 'Materials range from classic sources to current tools, all oriented around data literacy, risk, voting systems, and fair division. Later courses in the department will assume familiarity with data literacy, risk, voting systems, and fair division.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'e7629b27-def7-442c-ad91-0bdbd9afc754', 'a2b22222-0000-4000-a000-000000000001', false, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('0acd1fda-42a7-4b17-bc2e-9095c0542039', 'Differential Equations', 'Skills and concepts in dynamic systems, slope fields, and numerical solution methods.', 'Students spend most of class deeply engaged with dynamic systems, slope fields, and numerical solution methods, moving between explanation, practice, and critique. Group roles rotate so no one is permanently the scribe or the spokesperson.', ARRAY[12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'eda5e8a1-3b78-4271-9d46-f55fc1485e3e', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e','a9541047-4970-45a2-a979-70d58f9b8909'], ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075','']], NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('93da050f-cb08-4d50-a816-bb96b1b8b816', 'Mathematical Modeling', 'Emphasis on iterative models for scientific, civic, and policy questions.', 'Expect a mix of short drills and longer investigations organized around iterative models for scientific, civic, and policy questions. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Students leave with notes and graded work that document progress on iterative models for scientific, civic, and policy questions.', ARRAY[11,12], '', 'Mathematics', 'a2b20000-0000-4000-a000-000000000000', 'cb340799-a2cb-43e6-b9fb-5e803b530045', 'a2b22222-0000-4000-a000-000000000001', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('bdace620-2ccd-4f63-a2c9-26a9c27e431b', 'The Short Story', 'Compressed narrative, character, point of view, and literary craft.', 'Students spend most of class deeply engaged with compressed narrative, character, point of view, and literary craft, moving between explanation, practice, and critique. Students annotate their own errors and resubmit selected pieces after feedback. By the end, students should explain key ideas in compressed narrative, character, point of view, and literary craft clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '3afa968e-755c-4d69-82fe-a1f898012ba5', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('39f05ac1-f83e-4b3d-9c33-22a0b2d6f6aa', 'British Literature', 'Skills and concepts in British literary traditions from epic poetry to contemporary fiction.', 'Field-adjacent examples keep British literary traditions from epic poetry to contemporary fiction connected to situations students recognize outside school. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Students leave with notes and graded work that document progress on British literary traditions from epic poetry to contemporary fiction.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '5717f150-5ce4-4156-b1f4-6ddace252d1f', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('b9bda838-f4df-4c4a-9d75-68d7ad0dc22a', 'Digital Storytelling', 'Emphasis on multimodal narrative, audio, image, script, and online publication.', 'This offering is sequenced for the grades it serves, with multimodal narrative, audio, image, script, and online publication as the spine of major assignments. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'f22929bc-a6dc-4b44-99cb-d70c3400b533', 'a2b22222-0000-4000-a000-000000000002', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('d7aefffa-54f9-4bcd-adb2-b02f7438ecac', 'Literary Magazine', 'Skills and concepts in editorial selection, copyediting, design, and creative publication.', 'Field-adjacent examples keep editorial selection, copyediting, design, and creative publication connected to situations students recognize outside school. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '892a86c9-4712-4cfb-aa4d-eec89d887ce1', 'a2b22222-0000-4000-a000-000000000002', true, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('018867c5-a4ca-42b4-93c7-f1f8e4620f83', 'Literature and the Environment', 'For students ready to take on place writing, ecological imagination, and environmental justice.', 'Discussion norms matter here: peers must press on each other''s reasoning about place writing, ecological imagination, and environmental justice. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. Later courses in the department will assume familiarity with place writing, ecological imagination, and environmental justice.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '1cdd4dcb-9cf2-443e-b5a0-fe268532b348', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('c56a8749-cbb2-41fe-b1a3-03de606e2246', 'Science Fiction and Society', 'Attention to speculative worlds, technology, power, and social imagination.', 'Students who enroll should be ready for sustained attention to speculative worlds, technology, power, and social imagination and for revising unfinished work. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Later courses in the department will assume familiarity with speculative worlds, technology, power, and social imagination.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '80606d5d-2c12-4621-bbe7-34ea9b760ab1', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('7567401a-9080-402d-a4b5-f64254054e39', 'World Literature', 'Core work includes translated literature, cultural context, and comparative interpretation.', 'Teachers model professional habits while students pursue translated literature, cultural context, and comparative interpretation in pairs and on their own. Support structures include office hours, peer tutors, and optional extension problems for those who want more. By the end, students should explain key ideas in translated literature, cultural context, and comparative interpretation clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '643508fc-53f0-4161-9bbe-f3b3cfc2bc84', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('62b1475d-65b8-45a7-87e5-61c0b2be19a9', 'Detective Fiction', 'Lab- and project-driven work on mystery structure, clues, deduction, justice, and genre history.', 'Expect a mix of short drills and longer investigations organized around mystery structure, clues, deduction, justice, and genre history. By the end, students should explain key ideas in mystery structure, clues, deduction, justice, and genre history clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '794fb65a-9721-4825-a3ef-6bad77c509b9', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('2f1e1670-bbf7-4922-a332-410fda940d81', 'Grammar and Style', 'Lab- and project-driven work on sentence craft, usage, punctuation, clarity, and rhetorical effect.', 'Expect a mix of short drills and longer investigations organized around sentence craft, usage, punctuation, clarity, and rhetorical effect. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Later courses in the department will assume familiarity with sentence craft, usage, punctuation, clarity, and rhetorical effect.', ARRAY[9,10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '4a11636f-93ac-4eef-8c66-fba225183a90', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('72ba0930-25cd-4447-b296-650bc093eaf5', 'Advanced Composition', 'Reading, writing, and analysis focused on style, structure, revision, and writing for varied audiences.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how style, structure, revision, and writing for varied audiences is used. Students annotate their own errors and resubmit selected pieces after feedback. Students leave with notes and graded work that document progress on style, structure, revision, and writing for varied audiences.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '5717c251-10f0-41b9-b63f-507ec3145bb1', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('bccad355-75aa-48cb-bf21-1776343b2eef', 'Literature of the African Diaspora', 'Reading, writing, and analysis focused on diasporic identity, memory, resistance, and literary innovation.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how diasporic identity, memory, resistance, and literary innovation is used. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about diasporic identity, memory, resistance, and literary innovation under modest time pressure.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '706c2ef7-f068-4359-87eb-9ecf8c9db032', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('793e6af7-5c5a-4d70-93b1-c83824e46a6c', 'Contemporary Fiction', 'Emphasis on recent novels, diverse narrators, form, and cultural debate.', 'This offering is sequenced for the grades it serves, with recent novels, diverse narrators, form, and cultural debate as the spine of major assignments. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. A final project or exam asks students to integrate what they learned about recent novels, diverse narrators, form, and cultural debate under modest time pressure.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'bed3febf-698d-45f8-bdb5-ed5f23c3df51', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('53de5242-8b03-4c97-bf57-f644c3210d27', 'Memoir and Personal Essay', 'Hands-on experience with memory, voice, scene, reflection, and ethical life writing.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into memory, voice, scene, reflection, and ethical life writing, others synthesize. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '71c4085e-1566-4314-b182-df115f340349', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('0e0c8747-6382-4ed9-b265-46213c2be65a', 'Asian American Literature', 'Lab- and project-driven work on migration, belonging, family, language, and literary form.', 'Expect a mix of short drills and longer investigations organized around migration, belonging, family, language, and literary form. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about migration, belonging, family, language, and literary form under modest time pressure.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '63121fdb-7839-460f-9185-8d520e9b11d0', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('7db47da3-df0d-41b2-9ac5-b41226a75ff9', 'Argument and Persuasion', 'Emphasis on logical claims, credible evidence, counterargument, and civic rhetoric.', 'This offering is sequenced for the grades it serves, with logical claims, credible evidence, counterargument, and civic rhetoric as the spine of major assignments. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '51006299-5d61-48e6-9f18-30e89e5d2ad9', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('89731252-897c-4a53-9a58-55bb02a6a511', 'Journalism Lab', 'Core work includes collaborative reporting, editing, layout, and deadline-driven publication.', 'Teachers model professional habits while students pursue collaborative reporting, editing, layout, and deadline-driven publication in pairs and on their own. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about collaborative reporting, editing, layout, and deadline-driven publication under modest time pressure.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '38fb4007-3c98-424b-b4aa-a0c19c967c2d', 'a2b22222-0000-4000-a000-000000000002', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('2420cb2c-ee73-4e62-a950-946b3dbb109c', 'Journalism Lab', 'Core work includes collaborative reporting, editing, layout, and deadline-driven publication.', 'Teachers model professional habits while students pursue collaborative reporting, editing, layout, and deadline-driven publication in pairs and on their own. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about collaborative reporting, editing, layout, and deadline-driven publication under modest time pressure.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '38fb4007-3c98-424b-b4aa-a0c19c967c2d', 'a2b22222-0000-4000-a000-000000000002', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('a39e0f13-b896-458e-8ecc-0753668fbc77', 'English 10', 'Emphasis on world literature, rhetorical analysis, and sustained academic writing.', 'This offering is sequenced for the grades it serves, with world literature, rhetorical analysis, and sustained academic writing as the spine of major assignments. Group roles rotate so no one is permanently the scribe or the spokesperson. Students leave with notes and graded work that document progress on world literature, rhetorical analysis, and sustained academic writing.', ARRAY[10], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '05768a0e-a2f3-4ba5-a8f0-ec1250ef830f', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('9b90e08a-5106-446e-bc31-3da11d24168d', 'Women''s Literature', 'An elective built around gender, authorship, literary canon, and intersectional perspectives.', 'Rather than racing through a checklist, the class returns repeatedly to gender, authorship, literary canon, and intersectional perspectives until ideas feel usable. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about gender, authorship, literary canon, and intersectional perspectives under modest time pressure.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'e8816995-cf9c-4177-94b4-6f2af04c9f1b', 'a2b22222-0000-4000-a000-000000000002', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 22, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('910bf10b-c31e-4e7f-afe3-e9d505be5435', 'Modern Drama', 'Core work includes twentieth-century plays, staging, dialogue, and social conflict.', 'Teachers model professional habits while students pursue twentieth-century plays, staging, dialogue, and social conflict in pairs and on their own. The teacher conferences mid-term to adjust challenge level without watering down standards. Later courses in the department will assume familiarity with twentieth-century plays, staging, dialogue, and social conflict.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '5c5ed5b9-3ac1-487b-8d70-edf21a9adc5d', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('3c44943d-d55c-4aa5-ae03-5ec7f58cdba3', 'Native American Literature', 'Core work includes Indigenous storytelling, sovereignty, place, and contemporary writing.', 'Teachers model professional habits while students pursue Indigenous storytelling, sovereignty, place, and contemporary writing in pairs and on their own. Students leave with notes and graded work that document progress on Indigenous storytelling, sovereignty, place, and contemporary writing.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'c30d5a72-1164-4ec0-a131-ba11d4735aa1', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('4c6d4144-e84f-461d-ab2a-c4812b6f606e', 'Public Speaking', 'Reading, writing, and analysis focused on speech organization, delivery, audience analysis, and confidence.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how speech organization, delivery, audience analysis, and confidence is used. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '1447418b-d071-4842-89cd-d7e4575e6146', 'a2b22222-0000-4000-a000-000000000002', true, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('1913feb7-22b3-434a-9604-13ac65a0b05f', 'Shakespeare', 'Reading, writing, and analysis focused on dramatic language, performance choices, history, and close reading.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how dramatic language, performance choices, history, and close reading is used. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Later courses in the department will assume familiarity with dramatic language, performance choices, history, and close reading.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '4ba71e9c-4b7e-4c8c-a349-feef424a74f5', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('54baba04-2e7b-4ae4-af6c-efbb1a957578', 'Queer Literature', 'Emphasis on identity, community, genre, and LGBTQ+ literary histories.', 'This offering is sequenced for the grades it serves, with identity, community, genre, and LGBTQ+ literary histories as the spine of major assignments. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Students leave with notes and graded work that document progress on identity, community, genre, and LGBTQ+ literary histories.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '87fa88ce-ba2f-4907-860b-7212508823cf', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('f888466f-2022-4da8-ab5b-2da6b12c170e', 'Young Adult Literature', 'Covers adolescent identity, genre conventions, readership, and critical response.', 'The term opens with concrete problems tied to adolescent identity, genre conventions, readership, and critical response, then widens toward independent work. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '90688e75-bdc1-48c6-b7d7-eeaae1a33385', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('09e5f522-7936-47fd-ad48-44af33412d70', 'Creative Writing Workshop', 'Hands-on experience with fiction, poetry, creative nonfiction, peer critique, and revision.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into fiction, poetry, creative nonfiction, peer critique, and revision, others synthesize. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Students leave with notes and graded work that document progress on fiction, poetry, creative nonfiction, peer critique, and revision.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '53e3cdd5-6590-4018-839e-96d6a0554b89', 'a2b22222-0000-4000-a000-000000000002', true, ARRAY[ARRAY['Instructor permission']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('c31947b0-5dae-48c7-b309-71e921992b13', 'Honors English 10', 'An elective built around comparative world literature and advanced evidence-based argument.', 'Rather than racing through a checklist, the class returns repeatedly to comparative world literature and advanced evidence-based argument until ideas feel usable. Group roles rotate so no one is permanently the scribe or the spokesperson. Students leave with notes and graded work that document progress on comparative world literature and advanced evidence-based argument.', ARRAY[10], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'c7a63fa0-404d-45d9-b77c-16d8d2186ed8', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('406f65f1-e4f4-44b2-9ebf-269dde68011e', 'American Literature', 'Builds from fundamentals of American voices, literary movements, and national identity.', 'Materials range from classic sources to current tools, all oriented around American voices, literary movements, and national identity. Assessments mix short quizzes with performance tasks that look more like real work than trap questions.', ARRAY[10,11], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '2fbaf7b5-d582-40a3-8428-8ac800afbae7', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('611e0088-06d8-4eb7-91ee-b08583a50e0e', 'Mythology and Epic', 'Skills and concepts in heroic traditions, archetypes, oral storytelling, and adaptation.', 'Field-adjacent examples keep heroic traditions, archetypes, oral storytelling, and adaptation connected to situations students recognize outside school. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. Later courses in the department will assume familiarity with heroic traditions, archetypes, oral storytelling, and adaptation.', ARRAY[9,10], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '14423f6f-c863-4597-8bc5-6b4b935dd0d9', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('b4d282ec-4a7e-4782-972f-70f48dd1e1ce', 'Latinx Literature', 'Lab- and project-driven work on bilingual expression, community, history, and narrative voice.', 'Expect a mix of short drills and longer investigations organized around bilingual expression, community, history, and narrative voice. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '4cbf2c24-5ecf-4bac-9dda-bf4d10896d8f', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('0829c161-92ac-4cac-90c7-aff819740e56', 'Gothic Literature', 'Suspense, the uncanny, social anxiety, and Gothic conventions.', 'Students spend most of class deeply engaged with suspense, the uncanny, social anxiety, and Gothic conventions, moving between explanation, practice, and critique. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Students leave with notes and graded work that document progress on suspense, the uncanny, social anxiety, and Gothic conventions.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'bfffaaf2-3913-42d2-ba2c-ab766f6e27e2', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('4416bbf4-d0ec-4174-b5bb-312921139a36', 'Satire and Comedy', 'Hands-on experience with irony, parody, comic form, cultural criticism, and performance.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into irony, parody, comic form, cultural criticism, and performance, others synthesize. Students leave with notes and graded work that document progress on irony, parody, comic form, cultural criticism, and performance.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'a79c1ccf-e853-411c-80a0-816f33285b25', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('9b8ade0d-4069-4740-84a4-958ad890c229', 'English 9', 'Covers close reading, analytical paragraphs, grammar, and research foundations.', 'The term opens with concrete problems tied to close reading, analytical paragraphs, grammar, and research foundations, then widens toward independent work. Later courses in the department will assume familiarity with close reading, analytical paragraphs, grammar, and research foundations.', ARRAY[9], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'e0d9ea74-adfc-47e3-986b-58953329e2a6', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('45dc0929-d319-4744-9bfc-30c6ec65f38a', 'Poetry and Poetics', 'Hands-on experience with poetic form, sound, imagery, interpretation, and original composition.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into poetic form, sound, imagery, interpretation, and original composition, others synthesize. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Later courses in the department will assume familiarity with poetic form, sound, imagery, interpretation, and original composition.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'a85b5072-7867-44c2-807b-d99d399d6e2c', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('b7a5920f-5743-46ea-a047-ccf8d89e6792', 'Graphic Novels', 'Seminar and studio approaches to sequential art, visual rhetoric, panel design, and literary interpretation.', 'Workshops, mini-lectures, and critiques rotate so that sequential art, visual rhetoric, panel design, and literary interpretation never stays only on a worksheet. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '2fd50919-2fba-405b-ae23-33d70b0b8b0a', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('6a8366fd-380f-4994-9cf0-41276d36f8b3', 'Literature and Film', 'Term work on adaptation, cinematic language, narrative structure, and interpretation.', 'Early assessments check fluency; later ones ask students to combine ideas related to adaptation, cinematic language, narrative structure, and interpretation. Students annotate their own errors and resubmit selected pieces after feedback. By the end, students should explain key ideas in adaptation, cinematic language, narrative structure, and interpretation clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', 'cd3c3f57-1d0d-4556-b853-75b31375ec24', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('2c105c69-38e1-4232-94cd-ae62b07830f8', 'Honors English 9', 'Skills and concepts in accelerated literary analysis, seminar discussion, and polished prose.', 'Field-adjacent examples keep accelerated literary analysis, seminar discussion, and polished prose connected to situations students recognize outside school. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '4ace5dda-f6f6-4e9d-9309-d63967192fb1', 'a2b22222-0000-4000-a000-000000000002', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('cd1d6427-d505-43b5-ab4c-b26b3c24faf1', 'AP English Literature and Composition', 'Skills and concepts in college-level literary interpretation and timed analytical writing.', 'Field-adjacent examples keep college-level literary interpretation and timed analytical writing connected to situations students recognize outside school. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '64dc4ca0-a114-42c6-8c3a-9a07681cf9de', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('13c4dbf7-27ba-4844-ab09-b30ab7922cfa', 'Journalism', 'Lab- and project-driven work on news judgment, reporting, interviewing, and ethical publication.', 'Expect a mix of short drills and longer investigations organized around news judgment, reporting, interviewing, and ethical publication. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '8d89b735-8df8-4c0a-8347-e5cc528d130c', 'a2b22222-0000-4000-a000-000000000002', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('362bb4aa-b285-4f2e-bc48-3ff8067ab597', 'Research Writing', 'Reading, writing, and analysis focused on inquiry design, source evaluation, citation, and extended academic prose.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how inquiry design, source evaluation, citation, and extended academic prose is used. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '4e20f530-bd1b-46c2-84b4-d42dc14058ff', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('4e77c8ed-3b08-45fe-b4dc-3b0cc132763f', 'AP English Language and Composition', 'Skills and concepts in rhetorical analysis, argument, synthesis, and nonfiction style.', 'Field-adjacent examples keep rhetorical analysis, argument, synthesis, and nonfiction style connected to situations students recognize outside school. Students annotate their own errors and resubmit selected pieces after feedback. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'English', 'a2b20000-0000-4000-a000-000000000000', '566f5f8d-b7e6-46e6-9f4d-4ba6b7647430', 'a2b22222-0000-4000-a000-000000000002', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('ac12cce1-f35c-4044-b9c8-fab214a51cf1', 'Paleontology', 'Applied study of fossils, evolution, ancient environments, and geological interpretation.', 'Safety, data notebooks, and uncertainty estimates sit alongside conceptual study of fossils, evolution, ancient environments, and geological interpretation. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Notebooks should show clean data practices alongside conceptual grasp of fossils, evolution, ancient environments, and geological interpretation.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '61626803-db3a-47cb-a5c8-b49d99683422', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('eef0ba8b-6fd0-4fb6-a013-d03e213fe8e5', 'Earth Science', 'Skills and concepts in geology, weather, oceans, planetary systems, and field observation.', 'Discussion norms matter here: peers must press on each other''s reasoning about geology, weather, oceans, planetary systems, and field observation. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. A lab practical or investigation write-up demonstrates command of geology, weather, oceans, planetary systems, and field observation.', ARRAY[9,10], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '70c1689f-d00a-45b4-af85-373f9644cc74', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('37fb718a-c53a-4216-8f65-b77aaab7ce88', 'Honors Physics', 'Applied study of calculus-ready mechanics, electricity, waves, and experimental modeling.', 'The term opens with concrete problems tied to calculus-ready mechanics, electricity, waves, and experimental modeling, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A lab practical or investigation write-up demonstrates command of calculus-ready mechanics, electricity, waves, and experimental modeling.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '942c1312-32b2-45ea-bbd7-34e2a44ba921', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('12fd03cd-0342-4c65-bfaa-18d6e9a6b6d9', 'AP Physics 1', 'College-prep attention to algebra-based mechanics, energy, momentum, rotation, and waves.', 'Teachers model professional habits while students pursue algebra-based mechanics, energy, momentum, rotation, and waves in pairs and on their own. Support structures include office hours, peer tutors, and optional extension problems for those who want more. A final project or exam asks students to integrate what they learned about algebra-based mechanics, energy, momentum, rotation, and waves under modest time pressure.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'bca79279-5d82-4269-bdcf-9cd0f4487697', 'a2b22222-0000-4000-a000-000000000003', false, NULL, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 22, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('3f66c4b3-ec02-4e0c-a165-0518a6edf2cf', 'Forensic Science', 'Lab- and project-driven work on evidence collection, trace analysis, toxicology, and scientific testimony.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into evidence collection, trace analysis, toxicology, and scientific testimony, others synthesize. Notebooks should show clean data practices alongside conceptual grasp of evidence collection, trace analysis, toxicology, and scientific testimony.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'bb58f585-e67c-4b65-a81b-433667adea27', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('8fd97c9f-133f-49d2-9f3b-e2022405f798', 'Organic Chemistry', 'A practical look at carbon compounds, functional groups, mechanisms, and synthesis.', 'Capstone planning begins early so students can shape personal angles on carbon compounds, functional groups, mechanisms, and synthesis. Reading loads stay manageable; the heavier lift is interpreting and producing original work. Notebooks should show clean data practices alongside conceptual grasp of carbon compounds, functional groups, mechanisms, and synthesis.', ARRAY[12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'ae94f2a8-29df-47ca-b9b5-5eb142888612', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('c5d9a11e-d3d1-4060-a9af-e4e69b606d8a', 'AP Chemistry', 'A practical look at college-level reactions, kinetics, equilibrium, thermodynamics, and analysis.', 'Early assessments check fluency; later ones ask students to combine ideas related to college-level reactions, kinetics, equilibrium, thermodynamics, and analysis. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. By the end, students should explain key ideas in college-level reactions, kinetics, equilibrium, thermodynamics, and analysis clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '742cf98c-063d-4489-b7b0-6ee08aecbd78', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('c2907d0d-6bf9-4f52-995b-a24dc8948075', 'Chemistry', 'Attention to matter, bonding, reactions, stoichiometry, and experimental measurement.', 'Students who enroll should be ready for sustained attention to matter, bonding, reactions, stoichiometry, and experimental measurement and for revising unfinished work. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. By the end, students should explain key ideas in matter, bonding, reactions, stoichiometry, and experimental measurement clearly and apply them without a scripted worksheet.', ARRAY[10,11], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '018a98c4-acea-488f-8ec1-56c16b179896', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('48f02bd3-bf5f-4b58-b052-74771c89b413', 'Biology', 'Lab- and project-driven work on cell biology, genetics, evolution, ecology, and laboratory investigation.', 'What looks like a narrow topic—cell biology, genetics, evolution, ecology, and laboratory investigation—becomes a route into bigger questions about evidence and craft. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in cell biology, genetics, evolution, ecology, and laboratory investigation clearly and apply them without a scripted worksheet.', ARRAY[9,10], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '57bed2a2-f9f9-44b4-81ff-5d55b1a509b1', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('93cf4d35-30e1-4085-a1c0-39b036af173e', 'AP Biology', 'Emphasis on college-level cellular processes, heredity, evolution, and ecology.', 'Capstone planning begins early so students can shape personal angles on college-level cellular processes, heredity, evolution, and ecology. Support structures include office hours, peer tutors, and optional extension problems for those who want more. A final project or exam asks students to integrate what they learned about college-level cellular processes, heredity, evolution, and ecology under modest time pressure.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '6c1f999a-51d2-4183-a17c-350d624424ca', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('ffd3dae8-4077-458d-ae3c-8ad978971af1', 'Microbiology', 'For students ready to take on microbial diversity, culturing, immunity, disease, and biotechnology.', 'Field-adjacent examples keep microbial diversity, culturing, immunity, disease, and biotechnology connected to situations students recognize outside school. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about microbial diversity, culturing, immunity, disease, and biotechnology under modest time pressure.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '64419449-4b17-4b0f-805b-e86a254e9caa', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('1e2a0044-908e-4f11-aa38-1872ee9a1688', 'Science Research Seminar', 'Emphasis on experimental design, literature review, data analysis, and scientific communication.', 'What looks like a narrow topic—experimental design, literature review, data analysis, and scientific communication—becomes a route into bigger questions about evidence and craft. By the end, students should explain key ideas in experimental design, literature review, data analysis, and scientific communication clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '684394a1-d51a-4d0b-bed7-2cc75de04297', 'a2b22222-0000-4000-a000-000000000003', true, NULL, NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('a74fb463-3ef7-46f6-9341-80856434f7d5', 'Meteorology', 'Practice with atmospheric structure, forecasting, storms, climate, and weather data.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how atmospheric structure, forecasting, storms, climate, and weather data is used. Group roles rotate so no one is permanently the scribe or the spokesperson.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '353ba4da-333f-4c77-b8d1-23f1a062fe33', 'a2b22222-0000-4000-a000-000000000003', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('5f427211-c34a-47df-b22b-07a64fcbc847', 'Neuroscience', 'Builds from fundamentals of neural communication, brain systems, behavior, and research methods.', 'Materials range from classic sources to current tools, all oriented around neural communication, brain systems, behavior, and research methods. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. A lab practical or investigation write-up demonstrates command of neural communication, brain systems, behavior, and research methods.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '1026d292-ac26-4379-98c8-1a51c110ca4b', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('f815b153-210b-433f-8239-d68fd80890d0', 'Anatomy and Physiology', 'Applied study of human body systems, structure, function, and clinical case studies.', 'Materials range from classic sources to current tools, all oriented around human body systems, structure, function, and clinical case studies. Students annotate their own errors and resubmit selected pieces after feedback. Notebooks should show clean data practices alongside conceptual grasp of human body systems, structure, function, and clinical case studies.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '4e1eaded-ba96-4316-acfc-8d614fcdada1', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 22, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('c24c8742-4ee7-4dea-9cc0-4d82d6a44a7b', 'Biochemistry', 'Builds from fundamentals of proteins, enzymes, metabolism, molecular structure, and laboratory analysis.', 'Safety, data notebooks, and uncertainty estimates sit alongside conceptual study of proteins, enzymes, metabolism, molecular structure, and laboratory analysis. Support structures include office hours, peer tutors, and optional extension problems for those who want more. By the end, students should explain key ideas in proteins, enzymes, metabolism, molecular structure, and laboratory analysis clearly and apply them without a scripted worksheet.', ARRAY[12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'd8542776-00d9-46d8-a8ec-3bf847104880', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('6c962a11-bc5e-4b79-b24c-68b5d703d7d1', 'Astronomy', 'An elective built around stars, planets, galaxies, cosmology, and observational methods.', 'Students spend most of class deeply engaged with stars, planets, galaxies, cosmology, and observational methods, moving between explanation, practice, and critique. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. By the end, students should explain key ideas in stars, planets, galaxies, cosmology, and observational methods clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '02b33512-4996-43f1-adcf-1f8590851cb8', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('52c65954-f52e-421d-880f-b1997798f321', 'Renewable Energy Science', 'Lab- and project-driven work on solar, wind, storage, efficiency, and energy-system tradeoffs.', 'Materials range from classic sources to current tools, all oriented around solar, wind, storage, efficiency, and energy-system tradeoffs. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. A lab practical or investigation write-up demonstrates command of solar, wind, storage, efficiency, and energy-system tradeoffs.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '2b7deb97-34bf-4de7-b9a0-2370cfffaf8c', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('eb3e7cbf-c948-4970-8da4-f8fd87f6093a', 'Genetics', 'For students ready to take on inheritance, gene expression, genomics, variation, and bioethics.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how inheritance, gene expression, genomics, variation, and bioethics is used. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Notebooks should show clean data practices alongside conceptual grasp of inheritance, gene expression, genomics, variation, and bioethics.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'a0a99db0-6afa-4935-a155-fb4c497603f5', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('d402891f-eabe-447c-949f-e4cda3a61b38', 'Laboratory Techniques', 'Term work on measurement, instrumentation, safety, documentation, and quality control.', 'Safety, data notebooks, and uncertainty estimates sit alongside conceptual study of measurement, instrumentation, safety, documentation, and quality control. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in measurement, instrumentation, safety, documentation, and quality control clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'f32dff3a-2338-48cf-b433-f9f84ba24f51', 'a2b22222-0000-4000-a000-000000000003', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 18, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('a2ba3f9e-277d-4c68-a8ff-1e16fe9ac923', 'Physics', 'Practice with motion, forces, energy, waves, electricity, and quantitative experiments.', 'Rather than racing through a checklist, the class returns repeatedly to motion, forces, energy, waves, electricity, and quantitative experiments until ideas feel usable. A final project or exam asks students to integrate what they learned about motion, forces, energy, waves, electricity, and quantitative experiments under modest time pressure.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'f1f5d879-4ccc-44f9-987a-377db4ca5d55', 'a2b22222-0000-4000-a000-000000000003', false, NULL, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('521f5104-bcbc-48c2-a2d1-23446ba8fa62', 'AP Environmental Science', 'Hands-on experience with ecosystems, resources, pollution, climate, and environmental policy.', 'Materials range from classic sources to current tools, all oriented around ecosystems, resources, pollution, climate, and environmental policy. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Notebooks should show clean data practices alongside conceptual grasp of ecosystems, resources, pollution, climate, and environmental policy.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'dacdb4d4-800c-48b7-bfa2-754cb402b646', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('054ccbd0-3700-454b-9a7a-d607cc422dcf', 'Marine Biology', 'Lab- and project-driven work on ocean ecosystems, marine organisms, conservation, and water analysis.', 'The term opens with concrete problems tied to ocean ecosystems, marine organisms, conservation, and water analysis, then widens toward independent work. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A final project or exam asks students to integrate what they learned about ocean ecosystems, marine organisms, conservation, and water analysis under modest time pressure.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '1d4878de-09c1-4818-bd88-e1c3aaf37e97', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('b25bc1ae-6bc6-435c-8a01-b72ac88f5c73', 'Oceanography', 'An elective built around ocean circulation, seafloor geology, chemistry, and climate connections.', 'Rather than racing through a checklist, the class returns repeatedly to ocean circulation, seafloor geology, chemistry, and climate connections until ideas feel usable. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. A lab practical or investigation write-up demonstrates command of ocean circulation, seafloor geology, chemistry, and climate connections.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '1bbf8b64-908e-4631-a96e-707c7373223e', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('e3b314ed-e8ef-474f-9abe-7aaf84442fc8', 'Geology', 'Builds from fundamentals of minerals, rocks, plate tectonics, deep time, and landscape processes.', 'Materials range from classic sources to current tools, all oriented around minerals, rocks, plate tectonics, deep time, and landscape processes. A lab practical or investigation write-up demonstrates command of minerals, rocks, plate tectonics, deep time, and landscape processes.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '8bcbc3d4-45d9-42fa-99a2-78cad21e68a3', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('3d2cf531-4333-48b8-a28d-d756843f7a3f', 'Zoology', 'Animal diversity, anatomy, behavior, evolution, and classification.', 'Field-adjacent examples keep animal diversity, anatomy, behavior, evolution, and classification connected to situations students recognize outside school. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about animal diversity, anatomy, behavior, evolution, and classification under modest time pressure.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '32272027-700c-4eb4-b8ad-59f95b8a8ac3', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('dec58c07-7f05-4d37-896f-04326fec4bb4', 'Environmental Science', 'Attention to ecology, human impacts, conservation, and local field research.', 'Discussion norms matter here: peers must press on each other''s reasoning about ecology, human impacts, conservation, and local field research. The teacher conferences mid-term to adjust challenge level without watering down standards. By the end, students should explain key ideas in ecology, human impacts, conservation, and local field research clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '235eafa6-891e-4f55-bf45-273dbda3f2db', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('2dcb25b2-91cb-4c39-8a52-79af5d3f342d', 'Honors Biology', 'Skills and concepts in accelerated molecular biology, genetics, evolution, and inquiry labs.', 'Labs are not add-ons: most weeks reserve time for designing, measuring, or analyzing work tied to accelerated molecular biology, genetics, evolution, and inquiry labs. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about accelerated molecular biology, genetics, evolution, and inquiry labs under modest time pressure.', ARRAY[9,10], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '06a3495c-86d9-466c-b1c2-21cc7482545d', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('dbd8f39a-01e9-4737-a608-1311ebd6465d', 'Botany', 'An elective built around plant anatomy, physiology, classification, ecology, and cultivation.', 'Students spend most of class deeply engaged with plant anatomy, physiology, classification, ecology, and cultivation, moving between explanation, practice, and critique. Notebooks should show clean data practices alongside conceptual grasp of plant anatomy, physiology, classification, ecology, and cultivation.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'd97df963-0689-4a5a-9ec3-f0654e8647f6', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('67d38d7f-6cfc-487e-a64d-f0e60d9321d5', 'AP Physics 2', 'Seminar and studio approaches to fluids, thermodynamics, electricity, magnetism, optics, and modern physics.', 'Rather than racing through a checklist, the class returns repeatedly to fluids, thermodynamics, electricity, magnetism, optics, and modern physics until ideas feel usable. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. A lab practical or investigation write-up demonstrates command of fluids, thermodynamics, electricity, magnetism, optics, and modern physics.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'c057a6b3-5131-475b-a7c1-ccbf46e072bf', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('57ae4eed-5c39-4cf2-9c36-f12921e71467', 'Climate Science', 'Hands-on experience with Earth''s energy balance, climate records, modeling, and solutions.', 'Capstone planning begins early so students can shape personal angles on Earth''s energy balance, climate records, modeling, and solutions. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A final project or exam asks students to integrate what they learned about Earth''s energy balance, climate records, modeling, and solutions under modest time pressure.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '3400a354-3fb7-4ce7-9f3b-0bb9a2d923a1', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('ae59d181-1fff-46fc-a860-e7ac5b7dd54b', 'AP Physics C: Mechanics', 'Builds from fundamentals of calculus-based kinematics, forces, energy, momentum, and rotation.', 'Early assessments check fluency; later ones ask students to combine ideas related to calculus-based kinematics, forces, energy, momentum, and rotation. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. A lab practical or investigation write-up demonstrates command of calculus-based kinematics, forces, energy, momentum, and rotation.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '7fb72281-84d7-4180-870d-016aec3bea0a', 'a2b22222-0000-4000-a000-000000000003', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('5ebb4bcf-9820-4005-a786-17a24bf18bfa', 'Ecology', 'Seminar and studio approaches to populations, communities, ecosystems, field sampling, and conservation.', 'Discussion norms matter here: peers must press on each other''s reasoning about populations, communities, ecosystems, field sampling, and conservation. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. A final project or exam asks students to integrate what they learned about populations, communities, ecosystems, field sampling, and conservation under modest time pressure.', ARRAY[10,11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'ec3e7e99-25a3-40cc-b522-0197369f74cf', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('937f4310-d698-4e50-bddb-e1d5df60dfa5', 'Epidemiology', 'Hands-on experience with disease patterns, study design, public-health data, and intervention.', 'This offering is sequenced for the grades it serves, with disease patterns, study design, public-health data, and intervention as the spine of major assignments. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A lab practical or investigation write-up demonstrates command of disease patterns, study design, public-health data, and intervention.', ARRAY[11,12], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', 'e8fbb480-a0dc-4fb6-ae3e-4a71eede2cfc', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('b6cd2e2d-ad84-45e9-84cf-9afbf1396755', 'Honors Chemistry', 'Emphasis on advanced atomic theory, equilibrium, thermochemistry, and quantitative labs.', 'Materials range from classic sources to current tools, all oriented around advanced atomic theory, equilibrium, thermochemistry, and quantitative labs. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A lab practical or investigation write-up demonstrates command of advanced atomic theory, equilibrium, thermochemistry, and quantitative labs.', ARRAY[10,11], '', 'Science', 'a2b20000-0000-4000-a000-000000000000', '370e99aa-2134-4684-a36e-a6032c7f5136', 'a2b22222-0000-4000-a000-000000000003', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('566a6a67-437f-4b21-a487-c022a2eabc05', 'Mobile App Development', 'Emphasis on interface design, device APIs, persistence, testing, and release workflows.', 'Expect a mix of short drills and longer investigations organized around interface design, device APIs, persistence, testing, and release workflows. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about interface design, device APIs, persistence, testing, and release workflows under modest time pressure.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'bc1a1393-c50e-4695-a105-882d04330829', 'a2b22222-0000-4000-a000-000000000004', false, NULL, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454'], ARRAY['Lab section required']], 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9b53c27a-3c33-4d76-a6b5-0756d4c48d7f', 'Competitive Programming', 'Hands-on experience with efficient algorithms, timed problem solving, testing, and code review.', 'Expect a mix of short drills and longer investigations organized around efficient algorithms, timed problem solving, testing, and code review. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Code reviews and write-ups show how students reasoned through problems in efficient algorithms, timed problem solving, testing, and code review.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '5222bc29-938d-40d4-8d02-40a9437cf093', 'a2b22222-0000-4000-a000-000000000004', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('ee83d626-7a2e-4033-a536-277a9cf3bce5', 'Advanced Cybersecurity', 'Lab- and project-driven work on penetration testing, incident response, forensics, and defensive engineering.', 'Early assessments check fluency; later ones ask students to combine ideas related to penetration testing, incident response, forensics, and defensive engineering. Code reviews and write-ups show how students reasoned through problems in penetration testing, incident response, forensics, and defensive engineering.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '3579a756-fb14-499f-b39e-af32eb3d9c46', 'a2b22222-0000-4000-a000-000000000004', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('9b05fe4c-3498-43be-8bb0-53a8d641cd6e', 'Software Engineering', 'Hands-on experience with requirements, architecture, teamwork, testing, documentation, and maintenance.', 'Version control, readability, and testing habits are graded alongside correctness in requirements, architecture, teamwork, testing, documentation, and maintenance. The teacher conferences mid-term to adjust challenge level without watering down standards. A final project or exam asks students to integrate what they learned about requirements, architecture, teamwork, testing, documentation, and maintenance under modest time pressure.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'a489c9c8-ea27-481d-bc07-b7917769fd05', 'a2b22222-0000-4000-a000-000000000004', false, NULL, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454','9352533d-9b5c-49ea-8426-6d64b653827e']], 18, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('106c2c86-80b7-4d5b-83b9-221882154da7', 'Robotics Programming', 'Applied study of sensors, actuators, feedback, autonomous behavior, and team integration.', 'The term opens with concrete problems tied to sensors, actuators, feedback, autonomous behavior, and team integration, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A working program or project demo anchors the final weeks'' focus on sensors, actuators, feedback, autonomous behavior, and team integration.', ARRAY[9,10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '112a9731-7ac9-46a7-84d1-d03d0eee12c3', 'a2b22222-0000-4000-a000-000000000004', true, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('2bfe5603-b550-4696-95f5-12c22d769581', 'Data Structures and Algorithms', 'Builds from fundamentals of lists, trees, graphs, complexity, searching, and sorting.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into lists, trees, graphs, complexity, searching, and sorting, others synthesize. The teacher conferences mid-term to adjust challenge level without watering down standards. By the end, students should explain key ideas in lists, trees, graphs, complexity, searching, and sorting clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'fb1af878-c12d-4ed9-a1eb-c2ca740b6423', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('1e1d47f5-084b-4a8d-bc8b-f91f7a46ad1f', 'Python Programming', 'Skills and concepts in Python syntax, functions, collections, testing, and small applications.', 'Teachers model professional habits while students pursue Python syntax, functions, collections, testing, and small applications in pairs and on their own. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about Python syntax, functions, collections, testing, and small applications under modest time pressure.', ARRAY[9,10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'b5b239ed-f50f-4772-8703-b9e03482fec5', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('000f24f4-7d49-44bc-b81f-6cf5e3b16bca', 'Artificial Intelligence', 'Hands-on experience with search, classification, neural networks, evaluation, and AI ethics.', 'The term opens with concrete problems tied to search, classification, neural networks, evaluation, and AI ethics, then widens toward independent work. Group roles rotate so no one is permanently the scribe or the spokesperson. By the end, students should explain key ideas in search, classification, neural networks, evaluation, and AI ethics clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '9f76ac2e-cf18-4eae-8eca-b45f75295dcb', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e','a9541047-4970-45a2-a979-70d58f9b8909'], ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075',''], ARRAY['Department approval','']], ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454','f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 18, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('8e95568c-ab36-48c7-9435-2b75320cd454', 'Intro to Computer Science', 'For students ready to take on algorithms, programming fundamentals, data, and responsible computing.', 'Rather than racing through a checklist, the class returns repeatedly to algorithms, programming fundamentals, data, and responsible computing until ideas feel usable. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Code reviews and write-ups show how students reasoned through problems in algorithms, programming fundamentals, data, and responsible computing.', ARRAY[9,10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '80bf708d-a448-4369-8c26-8075b945b0d7', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9952a166-7571-4f52-9744-0d72af13eb05', 'AP Computer Science Principles', 'Applied study of creative computing, data, networks, algorithms, and digital impact.', 'Materials range from classic sources to current tools, all oriented around creative computing, data, networks, algorithms, and digital impact. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A working program or project demo anchors the final weeks'' focus on creative computing, data, networks, algorithms, and digital impact.', ARRAY[9,10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'df449e6a-114b-475d-b820-5887fd19f278', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('87384194-7eb9-462e-95f2-295a6d67b71f', 'Database Design', 'Emphasis on relational modeling, SQL, normalization, transactions, and application data.', 'Materials range from classic sources to current tools, all oriented around relational modeling, SQL, normalization, transactions, and application data. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. A working program or project demo anchors the final weeks'' focus on relational modeling, SQL, normalization, transactions, and application data.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'f06412e3-4aa6-4b74-912c-b8f2891781bd', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('fec24fb5-47ef-4261-b5b5-bee35d0c8d20', 'Game Programming', 'Lab- and project-driven work on game loops, physics, input, animation, and iterative level design.', 'Early assessments check fluency; later ones ask students to combine ideas related to game loops, physics, input, animation, and iterative level design. Group roles rotate so no one is permanently the scribe or the spokesperson. A working program or project demo anchors the final weeks'' focus on game loops, physics, input, animation, and iterative level design.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '0d0a2a63-11e7-4d70-b9c0-0be437bdc3f5', 'a2b22222-0000-4000-a000-000000000004', true, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('55fe3aa5-fa55-4ceb-b29a-7fdb95603adf', 'Java Programming', 'Builds from fundamentals of Java classes, control flow, collections, debugging, and application design.', 'This offering is sequenced for the grades it serves, with Java classes, control flow, collections, debugging, and application design as the spine of major assignments. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about Java classes, control flow, collections, debugging, and application design under modest time pressure.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'f9c8df17-d72d-4678-a4e5-d583e2f12c2e', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('9b4ffa5f-1a80-4686-8308-8d0be94036b7', 'Cybersecurity Fundamentals', 'Term work on threat models, secure systems, cryptography, networks, and ethics.', 'This offering is sequenced for the grades it serves, with threat models, secure systems, cryptography, networks, and ethics as the spine of major assignments. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A working program or project demo anchors the final weeks'' focus on threat models, secure systems, cryptography, networks, and ethics.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'e229dc05-ba8e-4c59-aa9a-0e1c4ce644d4', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('015d1b49-a940-4970-beda-2fa871f58f3c', 'Human-Computer Interaction', 'An elective built around user research, prototyping, accessibility, usability, and interface evaluation.', 'Workshops, mini-lectures, and critiques rotate so that user research, prototyping, accessibility, usability, and interface evaluation never stays only on a worksheet. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Code reviews and write-ups show how students reasoned through problems in user research, prototyping, accessibility, usability, and interface evaluation.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '2da7a789-833d-4d13-b3a3-a5a5c11831ba', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('2e99cc69-669d-4ae0-b4fe-d14432c37145', 'Cloud Computing', 'A practical look at virtual infrastructure, containers, services, reliability, and deployment.', 'This offering is sequenced for the grades it serves, with virtual infrastructure, containers, services, reliability, and deployment as the spine of major assignments. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about virtual infrastructure, containers, services, reliability, and deployment under modest time pressure.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'a11c46fb-874a-4cc1-988f-9120d9b1fdf4', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 18, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('f05fb3d4-8a48-430d-b031-6a12a876d7fa', 'Computer Science Capstone', 'Applied study of independent software planning, implementation, evaluation, and presentation.', 'Expect a mix of short drills and longer investigations organized around independent software planning, implementation, evaluation, and presentation. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Code reviews and write-ups show how students reasoned through problems in independent software planning, implementation, evaluation, and presentation.', ARRAY[12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'c36df314-fe3f-4d8e-a250-f681c7527d3d', 'a2b22222-0000-4000-a000-000000000004', true, NULL, NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('b6bdcf10-33e1-4a68-90d2-241f9c27c3cd', 'Data Science', 'Applied study of data cleaning, visualization, statistics, coding, and reproducible analysis.', 'Expect a mix of short drills and longer investigations organized around data cleaning, visualization, statistics, coding, and reproducible analysis. Code reviews and write-ups show how students reasoned through problems in data cleaning, visualization, statistics, coding, and reproducible analysis.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '762c28a3-f446-49e8-a1dd-f6c37c4fbbf0', 'a2b22222-0000-4000-a000-000000000004', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('49c81897-675d-4296-bf01-e6fe4cc9f90b', 'Computer Graphics', 'Applied study of raster images, vectors, transformations, rendering, and visual simulation.', 'The term opens with concrete problems tied to raster images, vectors, transformations, rendering, and visual simulation, then widens toward independent work. Reading loads stay manageable; the heavier lift is interpreting and producing original work. Code reviews and write-ups show how students reasoned through problems in raster images, vectors, transformations, rendering, and visual simulation.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'c8eb1873-425b-402c-8eb2-c2f79dcd6c70', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('aff74140-df9f-4d80-bf2e-3bb3493b574b', 'AP Computer Science A', 'A practical look at object-oriented Java, algorithms, data structures, and program design.', 'Capstone planning begins early so students can shape personal angles on object-oriented Java, algorithms, data structures, and program design. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A working program or project demo anchors the final weeks'' focus on object-oriented Java, algorithms, data structures, and program design.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'e6953456-5e84-4796-90c1-9858956c5036', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('8fdc9306-2b12-4e06-979f-b15cc1aa61cf', 'Web Development I', 'Core work includes semantic HTML, modern CSS, JavaScript, accessibility, and deployment.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how semantic HTML, modern CSS, JavaScript, accessibility, and deployment is used. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. A final project or exam asks students to integrate what they learned about semantic HTML, modern CSS, JavaScript, accessibility, and deployment under modest time pressure.', ARRAY[9,10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '01e309df-7cc5-48fd-b843-b8e0fa4b3ebd', 'a2b22222-0000-4000-a000-000000000004', false, NULL, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454'], ARRAY['Lab section required']], 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('6ee21324-a111-40f9-bfd7-8965f8591e15', 'Embedded Systems', 'Skills and concepts in microcontrollers, digital signals, device interfaces, and real-time code.', 'Field-adjacent examples keep microcontrollers, digital signals, device interfaces, and real-time code connected to situations students recognize outside school. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'abcd5814-5740-44c8-b6d3-a10a5365b310', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('308dae25-19e9-4583-8aec-f7830aeb99a3', 'Functional Programming', 'Term work on pure functions, recursion, immutable data, types, and compositional design.', 'Expect a mix of short drills and longer investigations organized around pure functions, recursion, immutable data, types, and compositional design. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. By the end, students should explain key ideas in pure functions, recursion, immutable data, types, and compositional design clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'b261bfdf-3836-4bb4-b265-dd5af2a1914f', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('d88714ef-8dab-4f43-917a-19441d20b1f4', 'Open Source Software', 'A practical look at version control, issue triage, collaborative development, and community norms.', 'This offering is sequenced for the grades it serves, with version control, issue triage, collaborative development, and community norms as the spine of major assignments. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about version control, issue triage, collaborative development, and community norms under modest time pressure.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'afb3d89d-6f8a-4950-a643-1a70838e1104', 'a2b22222-0000-4000-a000-000000000004', true, ARRAY[ARRAY['Successful completion of a placement exam','Counselor recommendation']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('49a09935-27a1-408b-a788-096b63a8bf3f', 'Operating Systems', 'For students ready to take on processes, memory, filesystems, concurrency, and system interfaces.', 'Students spend most of class deeply engaged with processes, memory, filesystems, concurrency, and system interfaces, moving between explanation, practice, and critique. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about processes, memory, filesystems, concurrency, and system interfaces under modest time pressure.', ARRAY[12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '4147cc7f-924a-4930-8d90-ded7a9588dd7', 'a2b22222-0000-4000-a000-000000000004', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('06808207-c1a4-436a-8205-007d35b61fcb', 'Web Development II', 'Covers component interfaces, APIs, state management, testing, and performance.', 'What looks like a narrow topic—component interfaces, APIs, state management, testing, and performance—becomes a route into bigger questions about evidence and craft. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A working program or project demo anchors the final weeks'' focus on component interfaces, APIs, state management, testing, and performance.', ARRAY[10,11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'f2d412df-360b-4c29-8b7b-ae8a17317d0f', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('63ac2d3f-f048-4a0c-a80b-d9bce2ab2437', 'Computer Networks', 'A practical look at protocols, routing, addressing, distributed communication, and network security.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into protocols, routing, addressing, distributed communication, and network security, others synthesize. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. A working program or project demo anchors the final weeks'' focus on protocols, routing, addressing, distributed communication, and network security.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', 'cdd06a8a-6b3c-4979-aa78-4617323eb555', 'a2b22222-0000-4000-a000-000000000004', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('392771f4-fc91-4428-bf2c-68da35a5dd82', 'Machine Learning', 'Builds from fundamentals of feature design, supervised learning, validation, and model interpretation.', 'Capstone planning begins early so students can shape personal angles on feature design, supervised learning, validation, and model interpretation. Code reviews and write-ups show how students reasoned through problems in feature design, supervised learning, validation, and model interpretation.', ARRAY[11,12], '', 'Computer Science', 'a2b20000-0000-4000-a000-000000000000', '7a3921d8-dda6-439c-98b1-8910f3939efb', 'a2b22222-0000-4000-a000-000000000004', false, NULL, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454','9352533d-9b5c-49ea-8426-6d64b653827e']], 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('9dd2cd95-9347-45ca-b8cb-05ab1057a0d0', 'AP World History: Modern', 'Global developments, comparison, causation, and document analysis since 1200.', 'Early assessments check fluency; later ones ask students to combine ideas related to global developments, comparison, causation, and document analysis since 1200. The teacher conferences mid-term to adjust challenge level without watering down standards. By the end, students should explain key ideas in global developments, comparison, causation, and document analysis since 1200 clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '9af3dba6-b234-44fb-8876-501d10e8b3a9', 'a2b22222-0000-4000-a000-000000000005', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('07350c77-9022-4c10-881f-5bd40d1d0288', 'History of South Asia', 'Covers empires, religions, colonialism, partition, democracy, and regional change.', 'The term opens with concrete problems tied to empires, religions, colonialism, partition, democracy, and regional change, then widens toward independent work. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '74815b47-4f14-42e5-ba8c-0359e77ce075', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('5406fa0e-e177-4e49-8119-78e0631fc80b', 'African American History', 'An elective built around Black life, resistance, institution building, culture, and political struggle.', 'Rather than racing through a checklist, the class returns repeatedly to Black life, resistance, institution building, culture, and political struggle until ideas feel usable. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about Black life, resistance, institution building, culture, and political struggle under modest time pressure.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '80707937-c656-401d-89fa-67122f6bad68', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('86f8d276-4c92-43ea-b39e-6cc92b750a4c', 'Medieval History', 'Reading, writing, and analysis focused on feudal societies, religion, trade, migration, and cultural exchange.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how feudal societies, religion, trade, migration, and cultural exchange is used. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about feudal societies, religion, trade, migration, and cultural exchange under modest time pressure.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '736c17f6-ebc0-457a-bccd-5fc0c1d90903', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('6583bd0d-8db9-47cc-887a-92cd5174a847', 'Middle Eastern History', 'Skills and concepts in empires, religions, colonial borders, nationalism, and modern states.', 'Field-adjacent examples keep empires, religions, colonial borders, nationalism, and modern states connected to situations students recognize outside school. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Later courses in the department will assume familiarity with empires, religions, colonial borders, nationalism, and modern states.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '37a9dfdf-286e-4d25-99e1-b5e508a9216a', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('ea6e756f-2b3d-4957-9cd2-c6adf47de378', 'United States History', 'Seminar and studio approaches to American political, social, economic, and cultural development.', 'Workshops, mini-lectures, and critiques rotate so that American political, social, economic, and cultural development never stays only on a worksheet. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. By the end, students should explain key ideas in American political, social, economic, and cultural development clearly and apply them without a scripted worksheet.', ARRAY[10,11], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '21d19be2-31c6-46ee-a6ce-de7dc4263f65', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('69bd75c1-7be9-402d-9141-714a449245ce', 'Military History', 'Attention to strategy, technology, logistics, leadership, and the human costs of war.', 'Students who enroll should be ready for sustained attention to strategy, technology, logistics, leadership, and the human costs of war and for revising unfinished work. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'a34acb83-a285-4570-8870-b28868ad28bc', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 22, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('60747626-260e-4374-b6e1-60e1bfe13b82', 'The Civil War and Reconstruction', 'Lab- and project-driven work on slavery, secession, warfare, emancipation, and contested reunion.', 'Expect a mix of short drills and longer investigations organized around slavery, secession, warfare, emancipation, and contested reunion. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students leave with notes and graded work that document progress on slavery, secession, warfare, emancipation, and contested reunion.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'c2c3f0ea-388e-4c5d-9744-90a03293d9fc', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('5c97f350-6190-415f-a2c6-bdd3769d6e36', 'History of Immigration', 'Emphasis on migration, law, labor, identity, exclusion, and community formation.', 'This offering is sequenced for the grades it serves, with migration, law, labor, identity, exclusion, and community formation as the spine of major assignments. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '561ce512-5ada-473e-8dc0-df30e631f40b', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('f143b8ce-2233-452d-a0ed-421d55facf48', 'East Asian History', 'Builds from fundamentals of Chinese, Japanese, and Korean states, cultures, exchanges, and transformations.', 'Materials range from classic sources to current tools, all oriented around Chinese, Japanese, and Korean states, cultures, exchanges, and transformations. Reading loads stay manageable; the heavier lift is interpreting and producing original work. By the end, students should explain key ideas in Chinese, Japanese, and Korean states, cultures, exchanges, and transformations clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'dede8f5e-b8b5-4113-bbcc-9614e55cebff', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('bdfd622d-4566-46ff-ae5f-9dcaf0b7e7d1', 'Oral History Workshop', 'Builds from fundamentals of interviewing, archival context, transcription, ethics, and public storytelling.', 'Materials range from classic sources to current tools, all oriented around interviewing, archival context, transcription, ethics, and public storytelling. Students annotate their own errors and resubmit selected pieces after feedback.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '8fe74877-cb90-42b1-9dbe-15af1d6b6b1b', 'a2b22222-0000-4000-a000-000000000005', true, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('f3c8e421-cc9e-404e-93a6-11830a40c3d8', 'AP United States History', 'Hands-on experience with college-level American history, primary sources, argument, and historical synthesis.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into college-level American history, primary sources, argument, and historical synthesis, others synthesize. The teacher conferences mid-term to adjust challenge level without watering down standards. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '886155d5-ce0e-4f59-839b-996bc15836c3', 'a2b22222-0000-4000-a000-000000000005', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('b71e1c81-5690-4455-8bec-b165e255659c', 'Latin American History', 'Builds from fundamentals of Indigenous societies, conquest, independence, inequality, and social movements.', 'Materials range from classic sources to current tools, all oriented around Indigenous societies, conquest, independence, inequality, and social movements. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '4c1c9550-755f-4933-a75f-b6ef56fdf887', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('86797664-a388-4346-aa28-e4b8fe0b7b8a', 'Modern European History', 'An elective built around revolution, industrialization, nationalism, empire, and integration.', 'Rather than racing through a checklist, the class returns repeatedly to revolution, industrialization, nationalism, empire, and integration until ideas feel usable. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '0f7328b9-266d-4cf1-9bc5-913c03e1f2c4', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 24, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('72bcfe08-b0ce-442d-a333-1d4c5c5bf4c9', 'The Cold War', 'Term work on ideology, diplomacy, proxy conflict, decolonization, and nuclear risk.', 'Early assessments check fluency; later ones ask students to combine ideas related to ideology, diplomacy, proxy conflict, decolonization, and nuclear risk. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in ideology, diplomacy, proxy conflict, decolonization, and nuclear risk clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'b3f1bee8-5723-4466-bb7c-0cbdcc36f341', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('14f186b6-0cd5-40d3-a64f-850271234820', 'History of the Americas', 'Reading, writing, and analysis focused on comparative Indigenous, colonial, revolutionary, and national histories.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how comparative Indigenous, colonial, revolutionary, and national histories is used. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Students leave with notes and graded work that document progress on comparative Indigenous, colonial, revolutionary, and national histories.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '0ce7368d-b07c-41af-852a-a3b27eb0084f', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('c4e9fd9b-bd76-4062-b66f-6fdd9332096e', 'LGBTQ+ History', 'Hands-on experience with identity, community, law, activism, culture, and historical memory.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into identity, community, law, activism, culture, and historical memory, others synthesize. By the end, students should explain key ideas in identity, community, law, activism, culture, and historical memory clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '4c2ebe43-cf31-4c58-847f-f9b6f40c4578', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('7e2c42e0-dfbc-43d3-ae19-2c6561267f30', 'Women''s History', 'Reading, writing, and analysis focused on women''s work, activism, family life, citizenship, and historical agency.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how women''s work, activism, family life, citizenship, and historical agency is used. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'cb459326-45dc-403b-b377-e21991e8f6a9', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('bcf92493-0455-4420-bb4c-50777b073676', 'AP European History', 'Covers European political, social, intellectual, and economic change since 1450.', 'The term opens with concrete problems tied to European political, social, intellectual, and economic change since 1450, then widens toward independent work. Students annotate their own errors and resubmit selected pieces after feedback. By the end, students should explain key ideas in European political, social, intellectual, and economic change since 1450 clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', 'd5876ba6-40c5-463a-b340-3ad11d7f3aa6', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('4ab33be5-68c4-44d8-af24-713934ba5b4f', 'Local History Research', 'An elective built around archives, maps, material culture, community memory, and public history.', 'Rather than racing through a checklist, the class returns repeatedly to archives, maps, material culture, community memory, and public history until ideas feel usable. Later courses in the department will assume familiarity with archives, maps, material culture, community memory, and public history.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '22048485-d41b-496e-a98c-69435df8c192', 'a2b22222-0000-4000-a000-000000000005', true, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('2788f7ac-b658-4122-af23-01c87d0a6525', 'African History', 'Builds from fundamentals of African states, trade networks, colonialism, independence, and contemporary change.', 'Materials range from classic sources to current tools, all oriented around African states, trade networks, colonialism, independence, and contemporary change. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '275de8db-2b30-43c3-abc2-fa0290f9f0b6', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('cec94e8f-6928-4437-a293-5d86ca2c562c', 'History Through Film', 'Applied study of historical interpretation, cinematic evidence, memory, and representation.', 'Capstone planning begins early so students can shape personal angles on historical interpretation, cinematic evidence, memory, and representation. Group roles rotate so no one is permanently the scribe or the spokesperson. By the end, students should explain key ideas in historical interpretation, cinematic evidence, memory, and representation clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '357faad1-1153-4ce4-91dd-a4c84bb0f65a', 'a2b22222-0000-4000-a000-000000000005', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('ee33e4fa-898d-46ff-9583-8a8a14a3f73b', 'Ancient Civilizations', 'Emphasis on early societies, belief systems, governance, trade, and archaeology.', 'This offering is sequenced for the grades it serves, with early societies, belief systems, governance, trade, and archaeology as the spine of major assignments. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Students leave with notes and graded work that document progress on early societies, belief systems, governance, trade, and archaeology.', ARRAY[9,10], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '949d7ce9-2bd0-4089-ac66-f3002bdc7f0a', 'a2b22222-0000-4000-a000-000000000005', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7', 'World History', 'An elective built around global civilizations, exchange, conflict, and change across eras.', 'Rather than racing through a checklist, the class returns repeatedly to global civilizations, exchange, conflict, and change across eras until ideas feel usable. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about global civilizations, exchange, conflict, and change across eras under modest time pressure.', ARRAY[9,10], '', 'History', 'a2b20000-0000-4000-a000-000000000000', '10f93b8f-95bf-46f3-b45d-97bcb58fa6e0', 'a2b22222-0000-4000-a000-000000000005', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('cb942845-4591-49e3-8b03-bae76cb51641', 'Spanish III', 'Hands-on experience with intermediate Spanish fluency, authentic texts, and extended conversation.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into intermediate Spanish fluency, authentic texts, and extended conversation, others synthesize. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'a830330e-c9a4-4915-b220-b539f5435421', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('67deb63f-c786-4efe-9af3-3f339a9cbf46', 'Spanish I', 'Attention to foundational Spanish conversation, listening, reading, writing, and culture.', 'Students who enroll should be ready for sustained attention to foundational Spanish conversation, listening, reading, writing, and culture and for revising unfinished work. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'afd8b231-a803-4816-8bb3-331cad28d2be', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('e78e1340-e071-49a3-b1a9-4ecc24a21d7a', 'AP French Language and Culture', 'Core work includes college-level French communication, interpretation, and cultural comparison.', 'Teachers model professional habits while students pursue college-level French communication, interpretation, and cultural comparison in pairs and on their own. A final project or exam asks students to integrate what they learned about college-level French communication, interpretation, and cultural comparison under modest time pressure.', ARRAY[11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'c7457c12-1016-4fa9-b86a-b80ae39ef392', 'a2b22222-0000-4000-a000-000000000006', false, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('1b6b34f3-c8b6-4a8f-913a-a36bd76eb453', 'Latin I', 'Lab- and project-driven work on classical vocabulary, grammar, translation, mythology, and Roman culture.', 'Expect a mix of short drills and longer investigations organized around classical vocabulary, grammar, translation, mythology, and Roman culture. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '5af33825-db82-4268-8171-dc499c24b23b', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('b18c49e0-1661-4dd7-9ccb-c1ffc3273565', 'AP Chinese Language and Culture', 'An elective built around advanced Mandarin communication, interpretation, and cultural knowledge.', 'Rather than racing through a checklist, the class returns repeatedly to advanced Mandarin communication, interpretation, and cultural knowledge until ideas feel usable. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about advanced Mandarin communication, interpretation, and cultural knowledge under modest time pressure.', ARRAY[11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'be38017d-f452-461b-88d9-8433e60d5823', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('8644b715-44c7-4c65-84c3-5c924fd28059', 'Spanish II', 'Practice with expanding Spanish communication, narration, grammar, and cultural knowledge.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how expanding Spanish communication, narration, grammar, and cultural knowledge is used. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in expanding Spanish communication, narration, grammar, and cultural knowledge clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '6a646a70-14f7-45d8-aec9-bff37ef91fb6', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('75b52396-1dde-4217-a0cd-b53c162062b2', 'Latin II', 'A practical look at intermediate Latin syntax, translation strategies, history, and literature.', 'What looks like a narrow topic—intermediate Latin syntax, translation strategies, history, and literature—becomes a route into bigger questions about evidence and craft. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. By the end, students should explain key ideas in intermediate Latin syntax, translation strategies, history, and literature clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '6e149bac-0d2a-4205-a4ac-1ac1b3ab2a16', 'a2b22222-0000-4000-a000-000000000006', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('e5a80c5a-4644-45f3-81a2-59bf01dcfeef', 'Mandarin Chinese II', 'Hands-on experience with developing Mandarin conversation, character literacy, and everyday communication.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into developing Mandarin conversation, character literacy, and everyday communication, others synthesize. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'f633d326-6220-4920-88d9-29c5252c666b', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('86c66ed5-e159-4da3-834d-88e0460a6ce9', 'French III', 'An elective built around intermediate French conversation, authentic media, and sustained writing.', 'Rather than racing through a checklist, the class returns repeatedly to intermediate French conversation, authentic media, and sustained writing until ideas feel usable. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about intermediate French conversation, authentic media, and sustained writing under modest time pressure.', ARRAY[10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'ea3ba57c-5317-43cc-bdec-ee5902df1c6a', 'a2b22222-0000-4000-a000-000000000006', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('98948415-1519-4b3d-91ad-fb84e0578af1', 'AP Spanish Language and Culture', 'Applied study of college-level Spanish communication, cultural comparison, and persuasive writing.', 'Capstone planning begins early so students can shape personal angles on college-level Spanish communication, cultural comparison, and persuasive writing. The teacher conferences mid-term to adjust challenge level without watering down standards. Students leave with notes and graded work that document progress on college-level Spanish communication, cultural comparison, and persuasive writing.', ARRAY[11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'c7e66999-ebf3-48f0-9b20-aa6d37016779', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('659ab119-c42f-41c8-8485-1314246e7f6c', 'French II', 'Emphasis on developing French narration, listening, grammar, and cultural understanding.', 'This offering is sequenced for the grades it serves, with developing French narration, listening, grammar, and cultural understanding as the spine of major assignments. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '40a2a7da-1644-44f5-9a80-5a75cdb6edee', 'a2b22222-0000-4000-a000-000000000006', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('cacfde1d-074c-4dfa-84f2-d8b8b1225281', 'French I', 'Emphasis on foundational French communication, pronunciation, literacy, and Francophone cultures.', 'This offering is sequenced for the grades it serves, with foundational French communication, pronunciation, literacy, and Francophone cultures as the spine of major assignments. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'bbd3a575-c1b4-453a-af3a-9518f701b3c7', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('b1310468-13a0-46aa-9d52-99fabdf81c9a', 'Spanish IV', 'Advanced Spanish discussion, composition, literature, and cultural analysis.', 'Students spend most of class deeply engaged with advanced Spanish discussion, composition, literature, and cultural analysis, moving between explanation, practice, and critique. Support structures include office hours, peer tutors, and optional extension problems for those who want more. A final project or exam asks students to integrate what they learned about advanced Spanish discussion, composition, literature, and cultural analysis under modest time pressure.', ARRAY[11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '3b5e07dc-5f2a-40f9-80f2-c730d11c376c', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('06cef436-7325-4f56-a3b3-accb3e235964', 'Mandarin Chinese I', 'Core work includes foundational Mandarin speaking, listening, characters, and cultural practices.', 'Teachers model professional habits while students pursue foundational Mandarin speaking, listening, characters, and cultural practices in pairs and on their own. Students annotate their own errors and resubmit selected pieces after feedback. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '615d9d24-31ef-4660-9a22-7a0954fc9192', 'a2b22222-0000-4000-a000-000000000006', false, NULL, ARRAY[ARRAY['Concurrent reading seminar']], 22, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('350f17e1-f8ca-47b1-b64c-3b36bfabb014', 'Latin III', 'Hands-on experience with advanced Latin prose and poetry, rhetoric, and historical context.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into advanced Latin prose and poetry, rhetoric, and historical context, others synthesize. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Later courses in the department will assume familiarity with advanced Latin prose and poetry, rhetoric, and historical context.', ARRAY[10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '61597d53-2eda-41f0-b6a1-b7924b3e173d', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('6c240970-e518-4517-bb9b-ae3f48f18925', 'Japanese II', 'Builds from fundamentals of developing Japanese communication, kanji, grammar, and cultural fluency.', 'Materials range from classic sources to current tools, all oriented around developing Japanese communication, kanji, grammar, and cultural fluency. Students annotate their own errors and resubmit selected pieces after feedback. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '79ae5487-1991-492f-af7b-45054b64efe1', 'a2b22222-0000-4000-a000-000000000006', false, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('93d43719-bd50-4fe3-8547-631122967038', 'American Sign Language I', 'Attention to foundational signing, receptive skills, Deaf culture, and visual grammar.', 'Students who enroll should be ready for sustained attention to foundational signing, receptive skills, Deaf culture, and visual grammar and for revising unfinished work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about foundational signing, receptive skills, Deaf culture, and visual grammar under modest time pressure.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '482fc65f-ba83-40dd-8a05-bfe2892498e9', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('88ebdb56-31f9-44dc-ab45-42f61644061d', 'Japanese I', 'Skills and concepts in foundational Japanese conversation, kana, introductory kanji, and culture.', 'Field-adjacent examples keep foundational Japanese conversation, kana, introductory kanji, and culture connected to situations students recognize outside school. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', '87bc3c9d-1190-4faa-8a5e-53c76cb26b67', 'a2b22222-0000-4000-a000-000000000006', false, ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('ead6f514-a61c-40d7-a340-bbb56b818d7c', 'Mandarin Chinese III', 'Intermediate Mandarin fluency, authentic texts, and cultural discussion.', 'Students spend most of class deeply engaged with intermediate Mandarin fluency, authentic texts, and cultural discussion, moving between explanation, practice, and critique. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'c0e30910-afc7-46c5-a544-63965a2d5f97', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('fa74b8b2-e5bc-42a6-a3fb-b93c6dba5aa4', 'French IV', 'For students ready to take on advanced French expression, literature, film, and cultural inquiry.', 'Discussion norms matter here: peers must press on each other''s reasoning about advanced French expression, literature, film, and cultural inquiry. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. Later courses in the department will assume familiarity with advanced French expression, literature, film, and cultural inquiry.', ARRAY[11,12], '', 'World Languages', 'a2b20000-0000-4000-a000-000000000000', 'ff9f9d2a-009f-4f1e-920f-17f9158956b7', 'a2b22222-0000-4000-a000-000000000006', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('e80f5516-58fc-4b99-ab7a-f6843e251909', 'Studio Art I', 'Practice with drawing, painting, composition, observation, and creative process.', 'Workshops, mini-lectures, and critiques rotate so that drawing, painting, composition, observation, and creative process never stays only on a worksheet. Students annotate their own errors and resubmit selected pieces after feedback. Students finish able to describe artistic choices related to drawing, painting, composition, observation, and creative process with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '5866d28a-baf2-44c3-9e2d-63a541c95dfa', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('7f770a80-ba4a-4592-96a5-6b125be34e92', 'Studio Art I', 'Practice with drawing, painting, composition, observation, and creative process.', 'Workshops, mini-lectures, and critiques rotate so that drawing, painting, composition, observation, and creative process never stays only on a worksheet. Students annotate their own errors and resubmit selected pieces after feedback. Students finish able to describe artistic choices related to drawing, painting, composition, observation, and creative process with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '5866d28a-baf2-44c3-9e2d-63a541c95dfa', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('0bfc7be7-eba0-4ba5-8c17-57efb24694f0', 'Studio Art I', 'Practice with drawing, painting, composition, observation, and creative process.', 'Workshops, mini-lectures, and critiques rotate so that drawing, painting, composition, observation, and creative process never stays only on a worksheet. Students annotate their own errors and resubmit selected pieces after feedback. Students finish able to describe artistic choices related to drawing, painting, composition, observation, and creative process with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '5866d28a-baf2-44c3-9e2d-63a541c95dfa', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('92d7a1dd-a9c5-43ed-9ed5-ea4713edc2be', 'Film Photography', 'Hands-on experience with manual exposure, darkroom printing, composition, and photographic history.', 'Capstone planning begins early so students can shape personal angles on manual exposure, darkroom printing, composition, and photographic history. Group roles rotate so no one is permanently the scribe or the spokesperson. Students finish able to describe artistic choices related to manual exposure, darkroom printing, composition, and photographic history with specific language.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', 'bf594856-25ed-4321-a4ff-d6454e945e27', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('b253156c-64ae-48b3-81d4-c9dfb874c128', 'Graphic Design', 'Covers typography, layout, branding, hierarchy, and visual communication.', 'Early assessments check fluency; later ones ask students to combine ideas related to typography, layout, branding, hierarchy, and visual communication. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Students finish able to describe artistic choices related to typography, layout, branding, hierarchy, and visual communication with specific language.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '3baae1a8-93d7-4c28-9687-92cc971e7aaf', 'a2b22222-0000-4000-a000-000000000007', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('da8e8877-e5b6-42fc-adf5-c3f3c1c0858c', 'Printmaking', 'Lab- and project-driven work on relief, intaglio, screen printing, editions, and graphic composition.', 'Capstone planning begins early so students can shape personal angles on relief, intaglio, screen printing, editions, and graphic composition. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Students finish able to describe artistic choices related to relief, intaglio, screen printing, editions, and graphic composition with specific language.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '1ba65f4d-2f32-4299-b4df-b447324e0f96', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('30db3987-c272-4d70-aee3-245b3bb154fe', 'Portfolio Development', 'Seminar and studio approaches to personal artistic direction, advanced revision, documentation, and presentation.', 'Rather than racing through a checklist, the class returns repeatedly to personal artistic direction, advanced revision, documentation, and presentation until ideas feel usable. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. By the end, students should explain key ideas in personal artistic direction, advanced revision, documentation, and presentation clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', 'd5e264e2-1baa-4bb2-aa5e-330e6c79f6fd', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('cc80131e-48fb-4d3f-977e-2a439d794cd4', 'AP Studio Art: Drawing', 'Hands-on experience with sustained drawing inquiry, experimentation, revision, and portfolio curation.', 'Materials range from classic sources to current tools, all oriented around sustained drawing inquiry, experimentation, revision, and portfolio curation. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint.', ARRAY[11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '1c23c085-2052-4d92-baf9-6929adf45337', 'a2b22222-0000-4000-a000-000000000007', false, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('88b9b55b-d9fe-4645-9b19-021bf6d976cd', 'Drawing and Illustration', 'Seminar and studio approaches to observational drawing, visual storytelling, media, and illustration techniques.', 'Students who enroll should be ready for sustained attention to observational drawing, visual storytelling, media, and illustration techniques and for revising unfinished work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', 'c16f801e-1dfc-49b4-bc4d-4403b8f2442c', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('1ec43e89-b2e1-418f-a6ba-48144cfd5776', 'Ceramics Studio', 'Attention to hand-building, wheel throwing, glazing, firing, and ceramic design.', 'Teachers model professional habits while students pursue hand-building, wheel throwing, glazing, firing, and ceramic design in pairs and on their own. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A public or classroom showcase makes student work on hand-building, wheel throwing, glazing, firing, and ceramic design visible beyond the studio.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '4e000835-5801-4c69-9f52-ad8bd4b54b4f', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('d6530a0d-20e9-47f1-8bfa-74ab5877e220', 'Ceramics Studio', 'Attention to hand-building, wheel throwing, glazing, firing, and ceramic design.', 'Teachers model professional habits while students pursue hand-building, wheel throwing, glazing, firing, and ceramic design in pairs and on their own. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A public or classroom showcase makes student work on hand-building, wheel throwing, glazing, firing, and ceramic design visible beyond the studio.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '4e000835-5801-4c69-9f52-ad8bd4b54b4f', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('7077209b-edac-4b75-8da4-f7d93d90ee5c', 'Art History', 'Core work includes global visual traditions, formal analysis, context, and museum interpretation.', 'Discussion norms matter here: peers must press on each other''s reasoning about global visual traditions, formal analysis, context, and museum interpretation. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in global visual traditions, formal analysis, context, and museum interpretation clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '0e7b0b64-1752-4dd6-a222-2ecbc8501d21', 'a2b22222-0000-4000-a000-000000000007', false, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('59170057-9023-40d2-b9a7-9e20e1212860', 'Fashion Design', 'For students ready to take on textiles, garment concepts, sketching, construction, and sustainable design.', 'Studio / rehearsal time dominates; reflection journals document decisions related to textiles, garment concepts, sketching, construction, and sustainable design. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students finish able to describe artistic choices related to textiles, garment concepts, sketching, construction, and sustainable design with specific language.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', 'c2a2fd6b-5990-4678-86b5-08071fe3822b', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('66a500a6-3070-4f02-9468-e33c17c4813f', 'Studio Art II', 'Applied study of advanced studio techniques, personal voice, critique, and portfolio development.', 'Expect a mix of short drills and longer investigations organized around advanced studio techniques, personal voice, critique, and portfolio development. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about advanced studio techniques, personal voice, critique, and portfolio development under modest time pressure.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', 'a6321c5f-ab5f-4eea-8154-563e501acf19', 'a2b22222-0000-4000-a000-000000000007', true, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('9bc1b3e4-33f6-4b15-85be-c00b81321d16', 'Digital Photography', 'Builds from fundamentals of camera controls, composition, lighting, editing, and visual narrative.', 'Early assessments check fluency; later ones ask students to combine ideas related to camera controls, composition, lighting, editing, and visual narrative. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students finish able to describe artistic choices related to camera controls, composition, lighting, editing, and visual narrative with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '3e95e6db-d6d6-4a87-baf8-af5b454557cb', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('e76ea6b0-869b-47b5-83f7-6441ff08c901', 'Digital Photography', 'Builds from fundamentals of camera controls, composition, lighting, editing, and visual narrative.', 'Early assessments check fluency; later ones ask students to combine ideas related to camera controls, composition, lighting, editing, and visual narrative. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students finish able to describe artistic choices related to camera controls, composition, lighting, editing, and visual narrative with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '3e95e6db-d6d6-4a87-baf8-af5b454557cb', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('d7992e8e-d8f0-4c21-8c0b-a4f237f5ff50', 'Digital Art', 'For students ready to take on raster and vector tools, digital painting, collage, and creative workflow.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how raster and vector tools, digital painting, collage, and creative workflow is used. The teacher conferences mid-term to adjust challenge level without watering down standards. Students finish able to describe artistic choices related to raster and vector tools, digital painting, collage, and creative workflow with specific language.', ARRAY[9,10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '5620b059-8869-449e-802a-ca5a845e0c79', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('58075cdc-5240-4a9b-b4cb-6340a326a285', 'Sculpture', 'Practice with three-dimensional form, construction, carving, casting, and installation.', 'Students spend most of class deeply engaged with three-dimensional form, construction, carving, casting, and installation, moving between explanation, practice, and critique. Assessments mix short quizzes with performance tasks that look more like real work than trap questions.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '6cdda857-cae0-43ad-9330-d48585f86cbe', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('23be5940-8ba4-4ed3-8bad-ac0240c34c69', 'Painting', 'Core work includes color, surface, composition, materials, and expressive visual language.', 'Rather than racing through a checklist, the class returns repeatedly to color, surface, composition, materials, and expressive visual language until ideas feel usable. Students annotate their own errors and resubmit selected pieces after feedback.', ARRAY[10,11,12], '', 'Arts', 'a2b20000-0000-4000-a000-000000000000', '9706be29-7ec9-4892-9974-a2207a3d863f', 'a2b22222-0000-4000-a000-000000000007', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('32b5e1f1-05b8-4765-8c4d-9732ffa3b58e', 'Physical Education Foundations', 'Builds from fundamentals of fitness principles, movement skills, teamwork, and lifelong activity.', 'Students track personal goals while practicing fitness principles, movement skills, teamwork, and lifelong activity in progressive stations or small-sided games. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Students leave with personal routines they can continue outside class involving fitness principles, movement skills, teamwork, and lifelong activity.', ARRAY[9], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'c3e6ba58-1738-480e-989b-6a80b2695df8', 'a2b22222-0000-4000-a000-000000000008', false, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('d9d7b152-fe99-4c15-bab8-c843c07c3c67', 'Personal Fitness', 'Applied study of goal setting, fitness assessment, training principles, and healthy routines.', 'The term opens with concrete problems tied to goal setting, fitness assessment, training principles, and healthy routines, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Fitness logs and skill checklists show measurable improvement related to goal setting, fitness assessment, training principles, and healthy routines.', ARRAY[10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '75ab6ba9-532c-4136-b7d9-25f21aa102eb', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('e5774ea4-35d1-4ea0-b55a-94b9b7e95c4c', 'Basketball Skills', 'Core work includes ball handling, shooting, defense, tactics, and cooperative play.', 'Workshops, mini-lectures, and critiques rotate so that ball handling, shooting, defense, tactics, and cooperative play never stays only on a worksheet. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Fitness logs and skill checklists show measurable improvement related to ball handling, shooting, defense, tactics, and cooperative play.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '8719e5e6-31d9-41bb-8353-b8afc8caaf80', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('dd0086b0-157d-450a-a9a9-d6d34f59398b', 'Sports Performance', 'An elective built around speed, agility, power, recovery, and sport-specific conditioning.', 'Discussion norms matter here: peers must press on each other''s reasoning about speed, agility, power, recovery, and sport-specific conditioning. Fitness logs and skill checklists show measurable improvement related to speed, agility, power, recovery, and sport-specific conditioning.', ARRAY[10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'd0c6728a-1d97-4bfc-821e-a0d04da16f16', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('9d3a0e80-c3a6-4df7-9710-7cfe6d5abe62', 'Lifetime Recreation', 'Builds from fundamentals of accessible recreational activities, wellness planning, and active leisure.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into accessible recreational activities, wellness planning, and active leisure, others synthesize. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Fitness logs and skill checklists show measurable improvement related to accessible recreational activities, wellness planning, and active leisure.', ARRAY[11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '6f9641fd-b2c2-43af-9f87-ee9307424f14', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('a6376d67-1067-48de-a888-feb9b9d103b8', 'Strength Training', 'Builds from fundamentals of safe resistance technique, program design, mobility, and progressive training.', 'The term opens with concrete problems tied to safe resistance technique, program design, mobility, and progressive training, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Fitness logs and skill checklists show measurable improvement related to safe resistance technique, program design, mobility, and progressive training.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'b6f54df7-ce8d-42c0-8b04-3ba13e5a0f6c', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('6ab7e16a-8bd9-4243-8640-6e7bbc20fac8', 'Strength Training', 'Builds from fundamentals of safe resistance technique, program design, mobility, and progressive training.', 'The term opens with concrete problems tied to safe resistance technique, program design, mobility, and progressive training, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Fitness logs and skill checklists show measurable improvement related to safe resistance technique, program design, mobility, and progressive training.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'b6f54df7-ce8d-42c0-8b04-3ba13e5a0f6c', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('8ef30103-e2fa-4eaf-b77f-b241f8643751', 'Soccer Skills', 'Attention to touch, passing, movement, defending, tactics, and match play.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how touch, passing, movement, defending, tactics, and match play is used. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. By the end, students should explain key ideas in touch, passing, movement, defending, tactics, and match play clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'a39bf52c-162b-4757-acf0-214a79f78ed8', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('39c916e3-2e02-4528-ac32-bfc048126159', 'Outdoor Education', 'An elective built around navigation, low-impact travel, risk management, and environmental stewardship.', 'Students spend most of class deeply engaged with navigation, low-impact travel, risk management, and environmental stewardship, moving between explanation, practice, and critique. Students annotate their own errors and resubmit selected pieces after feedback. A final project or exam asks students to integrate what they learned about navigation, low-impact travel, risk management, and environmental stewardship under modest time pressure.', ARRAY[10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '3e09094a-5bc8-4c4a-8690-8d10b8997581', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('adfd5124-c389-45df-86aa-c78a2dda866e', 'Team Sports', 'Skills and concepts in rules, strategy, communication, sportsmanship, and varied team games.', 'Teachers model professional habits while students pursue rules, strategy, communication, sportsmanship, and varied team games in pairs and on their own. A final project or exam asks students to integrate what they learned about rules, strategy, communication, sportsmanship, and varied team games under modest time pressure.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'dadaa7e5-5c4c-4e18-a583-a7c082eef0aa', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('bf5bad31-6c66-4ef1-abbb-315b5558d1dd', 'Individual Sports', 'Seminar and studio approaches to self-paced skill development in racquet, target, and lifetime activities.', 'Students spend most of class deeply engaged with self-paced skill development in racquet, target, and lifetime activities, moving between explanation, practice, and critique. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. By the end, students should explain key ideas in self-paced skill development in racquet, target, and lifetime activities clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '8cd9f185-474c-47dd-a33d-3bc7a1074cef', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('0ca55ed0-6de7-43bd-8111-1d3fc1cf6a7a', 'Dance Fitness', 'Builds from fundamentals of rhythm, coordination, cardiovascular conditioning, and movement sequences.', 'The term opens with concrete problems tied to rhythm, coordination, cardiovascular conditioning, and movement sequences, then widens toward independent work. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. A final project or exam asks students to integrate what they learned about rhythm, coordination, cardiovascular conditioning, and movement sequences under modest time pressure.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', '2f5f84ef-2c07-47ac-a115-05cb192a3c22', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('e700941a-b0a9-4773-9edd-3ad000e446aa', 'Swimming and Water Safety', 'Builds from fundamentals of stroke technique, endurance, rescue awareness, and aquatic confidence.', 'Students track personal goals while practicing stroke technique, endurance, rescue awareness, and aquatic confidence in progressive stations or small-sided games. The teacher conferences mid-term to adjust challenge level without watering down standards. Students leave with personal routines they can continue outside class involving stroke technique, endurance, rescue awareness, and aquatic confidence.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'a6acd568-abab-4781-9fef-05505f64859c', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('f8d3d9ea-49d9-4ea3-8210-f85064c309c1', 'Yoga Fitness', 'For students ready to take on posture, mobility, breath, balance, and mindful conditioning.', 'Workshops, mini-lectures, and critiques rotate so that posture, mobility, breath, balance, and mindful conditioning never stays only on a worksheet. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about posture, mobility, breath, balance, and mindful conditioning under modest time pressure.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'eb187d5c-ef86-419f-aa03-807eba35063e', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('2cbfd884-5d14-45e5-b24c-b20b63f01d62', 'Yoga Fitness', 'For students ready to take on posture, mobility, breath, balance, and mindful conditioning.', 'Workshops, mini-lectures, and critiques rotate so that posture, mobility, breath, balance, and mindful conditioning never stays only on a worksheet. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. A final project or exam asks students to integrate what they learned about posture, mobility, breath, balance, and mindful conditioning under modest time pressure.', ARRAY[9,10,11,12], '', 'Physical Education', 'a2b20000-0000-4000-a000-000000000000', 'eb187d5c-ef86-419f-aa03-807eba35063e', 'a2b22222-0000-4000-a000-000000000008', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('76abd752-0149-437d-b171-37ef904b50e8', 'Human Development', 'Applied study of physical, cognitive, emotional, and social change across the lifespan.', 'Capstone planning begins early so students can shape personal angles on physical, cognitive, emotional, and social change across the lifespan. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. A final project or exam asks students to integrate what they learned about physical, cognitive, emotional, and social change across the lifespan under modest time pressure.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'a8ef35d7-8c05-42c5-8096-487f28407115', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('0a8c0681-be5b-4523-90ba-8d58b124573d', 'AP Psychology', 'Emphasis on behavior, cognition, development, research methods, and psychological science.', 'This offering is sequenced for the grades it serves, with behavior, cognition, development, research methods, and psychological science as the spine of major assignments. A final project or exam asks students to integrate what they learned about behavior, cognition, development, research methods, and psychological science under modest time pressure.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '2b7d8d01-91f3-4e24-9676-af410fef02bd', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('9f23a6be-2847-477b-9818-55913671c69f', 'AP Human Geography', 'Skills and concepts in spatial patterns, population, culture, cities, and development.', 'Field-adjacent examples keep spatial patterns, population, culture, cities, and development connected to situations students recognize outside school. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint.', ARRAY[9,10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '8e497a64-6576-41fd-bdfd-8f5f6ff8c630', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('6e2f1bee-d6e1-4a30-870b-ee74bb5c14ea', 'AP Microeconomics', 'For students ready to take on consumer choice, firms, market structures, efficiency, and government intervention.', 'Discussion norms matter here: peers must press on each other''s reasoning about consumer choice, firms, market structures, efficiency, and government intervention. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Later courses in the department will assume familiarity with consumer choice, firms, market structures, efficiency, and government intervention.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'ffa8ed32-5615-4f3e-afaa-9acf9270a851', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('1fff39d1-fe0f-4481-b48c-a40f196f660d', 'Urban Studies', 'Practice with cities, housing, transportation, public space, inequality, and planning.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how cities, housing, transportation, public space, inequality, and planning is used. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about cities, housing, transportation, public space, inequality, and planning under modest time pressure.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'e71bf0d2-3c11-45e8-8275-aa7c277311ca', 'a2b22222-0000-4000-a000-000000000009', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('4753304b-a185-403a-b03a-7b9d954fd055', 'Psychology', 'Core work includes human thought, emotion, behavior, development, and research literacy.', 'Teachers model professional habits while students pursue human thought, emotion, behavior, development, and research literacy in pairs and on their own. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'b476b845-b45c-4650-92ee-7bb0d4a795b1', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('51f624b5-231a-4b29-999d-9a329ff34511', 'Political Science', 'Core work includes institutions, power, ideology, participation, and comparative government.', 'Teachers model professional habits while students pursue institutions, power, ideology, participation, and comparative government in pairs and on their own. Group roles rotate so no one is permanently the scribe or the spokesperson. Later courses in the department will assume familiarity with institutions, power, ideology, participation, and comparative government.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '666668a0-2655-4ad5-a0e5-2f047a41c445', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('40ab1d96-f63a-4449-b283-5814616c99be', 'Economics', 'A practical look at markets, incentives, public policy, personal choice, and economic evidence.', 'What looks like a narrow topic—markets, incentives, public policy, personal choice, and economic evidence—becomes a route into bigger questions about evidence and craft. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'fd60e8fc-8947-4e53-bc81-82c94cb49fb0', 'a2b22222-0000-4000-a000-000000000009', false, NULL, ARRAY[ARRAY['Concurrent enrollment in a math course']], 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('2206e997-b204-4480-ab76-3cf1aa8f8534', 'Sociology', 'Term work on social institutions, culture, inequality, groups, and sociological research.', 'Early assessments check fluency; later ones ask students to combine ideas related to social institutions, culture, inequality, groups, and sociological research. Support structures include office hours, peer tutors, and optional extension problems for those who want more.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'a11c56ef-7700-465c-b36b-d9f4f3dd515f', 'a2b22222-0000-4000-a000-000000000009', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 26, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('f4cfb9f5-2520-4992-896a-3b673bcf5f9d', 'AP Macroeconomics', 'Lab- and project-driven work on national output, inflation, unemployment, fiscal policy, and monetary policy.', 'Expect a mix of short drills and longer investigations organized around national output, inflation, unemployment, fiscal policy, and monetary policy. Reading loads stay manageable; the heavier lift is interpreting and producing original work. Students leave with notes and graded work that document progress on national output, inflation, unemployment, fiscal policy, and monetary policy.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '29182e63-cfbb-4fd7-83a8-7f80c3b3e2ad', 'a2b22222-0000-4000-a000-000000000009', false, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('14794303-0e1c-45d8-a307-d2f1d986f704', 'Criminology', 'Core work includes crime theories, justice institutions, evidence, policy, and social context.', 'Teachers model professional habits while students pursue crime theories, justice institutions, evidence, policy, and social context in pairs and on their own. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '9d8bc30c-e6cd-44a5-a7bb-b8072bbde1b8', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('43eba7b9-d383-4485-a454-0acad5677c67', 'Cultural Anthropology', 'Seminar and studio approaches to culture, kinship, belief, language, fieldwork, and human diversity.', 'Workshops, mini-lectures, and critiques rotate so that culture, kinship, belief, language, fieldwork, and human diversity never stays only on a worksheet. The teacher conferences mid-term to adjust challenge level without watering down standards. Students leave with notes and graded work that document progress on culture, kinship, belief, language, fieldwork, and human diversity.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'cdf47554-1a89-4fa0-97b8-7c38905f7f8a', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('213cbbb6-7f62-46bf-b86e-2e5215ded92e', 'Global Studies', 'Skills and concepts in interdependence, development, migration, conflict, and international cooperation.', 'Field-adjacent examples keep interdependence, development, migration, conflict, and international cooperation connected to situations students recognize outside school. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Students leave with notes and graded work that document progress on interdependence, development, migration, conflict, and international cooperation.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', 'd66b7a96-31ef-4fb7-9f22-27486f0ec59b', 'a2b22222-0000-4000-a000-000000000009', false, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 24, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('60a07c8a-a648-4dc0-8fb2-cb149ccf6c3f', 'Social Justice Studies', 'Emphasis on inequality, identity, institutions, movements, and community-based inquiry.', 'This offering is sequenced for the grades it serves, with inequality, identity, institutions, movements, and community-based inquiry as the spine of major assignments. Cross-course connections (when schedules allow) show how the same idea travels across disciplines.', ARRAY[10,11,12], '', 'Social Sciences', 'a2b20000-0000-4000-a000-000000000000', '992d8706-fe6a-4d1c-90c3-489320c0d2e2', 'a2b22222-0000-4000-a000-000000000009', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('967ef38f-9541-44db-a5e3-cd6da0ce40f7', 'Engineering Capstone', 'Hands-on experience with client-centered design, project management, prototyping, validation, and presentation.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into client-centered design, project management, prototyping, validation, and presentation, others synthesize. Students leave with notes and graded work that document progress on client-centered design, project management, prototyping, validation, and presentation.', ARRAY[12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '03b9a803-159d-4fbe-a940-76047b11cf73', 'a2b22222-0000-4000-a000-000000000010', true, NULL, NULL, 14, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('419eb21a-a64f-42e6-8712-710533050b88', 'Computer-Aided Design', 'Practice with parametric modeling, technical drawings, assemblies, and design communication.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how parametric modeling, technical drawings, assemblies, and design communication is used. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '35b3e9ec-7e33-492c-ad54-232da363c302', 'a2b22222-0000-4000-a000-000000000010', true, ARRAY[ARRAY['c2907d0d-6bf9-4f52-995b-a24dc8948075']], ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e']], 20, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('2c8d60f5-e142-4a22-bf14-39e58e07f000', 'Biomedical Engineering', 'Covers human-centered devices, biomechanics, biomaterials, and design ethics.', 'The term opens with concrete problems tied to human-centered devices, biomechanics, biomaterials, and design ethics, then widens toward independent work. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Later courses in the department will assume familiarity with human-centered devices, biomechanics, biomaterials, and design ethics.', ARRAY[11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '936ce9ca-826c-4925-a7af-a8afb95f968c', 'a2b22222-0000-4000-a000-000000000010', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('a9740b4b-fa33-4ee3-9e9d-f802956989d2', 'Environmental Engineering', 'Water, waste, air quality, remediation, and sustainable systems.', 'Students spend most of class deeply engaged with water, waste, air quality, remediation, and sustainable systems, moving between explanation, practice, and critique. Group roles rotate so no one is permanently the scribe or the spokesperson. Later courses in the department will assume familiarity with water, waste, air quality, remediation, and sustainable systems.', ARRAY[10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '06309703-2528-4404-8c71-06eaac791f3d', 'a2b22222-0000-4000-a000-000000000010', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('44e22c24-c188-43cc-b634-ee7331b76015', 'Aerospace Engineering', 'Term work on aerodynamics, propulsion, flight stability, orbital systems, and testing.', 'Early assessments check fluency; later ones ask students to combine ideas related to aerodynamics, propulsion, flight stability, orbital systems, and testing. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about aerodynamics, propulsion, flight stability, orbital systems, and testing under modest time pressure.', ARRAY[11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', 'eb5bd3d2-4553-4542-aec0-f685ac1c6b4f', 'a2b22222-0000-4000-a000-000000000010', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('a3dda549-1dce-478e-9bdb-a0c342eb9129', 'Mechanical Engineering', 'Emphasis on forces, mechanisms, machine elements, fabrication, and iterative testing.', 'This offering is sequenced for the grades it serves, with forces, mechanisms, machine elements, fabrication, and iterative testing as the spine of major assignments. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', 'fe2ae366-fff5-4948-8a80-80181d3b67ff', 'a2b22222-0000-4000-a000-000000000010', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('5e58b065-9ffe-4d22-8e25-f843b82aaebf', 'Electrical Engineering', 'Practice with circuits, sensors, signals, measurement, and electronic prototyping.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how circuits, sensors, signals, measurement, and electronic prototyping is used. Group roles rotate so no one is permanently the scribe or the spokesperson. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', 'dd0bbc31-5397-49b1-9a93-6b3a27030d11', 'a2b22222-0000-4000-a000-000000000010', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('40c0aff7-3a14-4b41-95f0-57408566bb55', 'Introduction to Engineering Design', 'Skills and concepts in design process, technical sketching, prototyping, testing, and documentation.', 'Field-adjacent examples keep design process, technical sketching, prototyping, testing, and documentation connected to situations students recognize outside school. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', 'd2dfcff4-f256-4ea7-a0dc-fbdceb529fdb', 'a2b22222-0000-4000-a000-000000000010', false, ARRAY[ARRAY['67deb63f-c786-4efe-9af3-3f339a9cbf46'], ARRAY['Native speaker assessment']], NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('47446467-5bbf-4e82-9573-e79e03f60ac1', 'Civil Engineering and Architecture', 'Applied study of structures, sites, materials, drafting, and sustainable built environments.', 'Capstone planning begins early so students can shape personal angles on structures, sites, materials, drafting, and sustainable built environments. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '3f708d8f-0ae2-4def-9621-c6bf32c04c46', 'a2b22222-0000-4000-a000-000000000010', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('aba6dc15-87f9-49c1-ae47-cb720a041624', 'Materials Science and Engineering', 'Covers material structure, properties, selection, failure, and testing.', 'The term opens with concrete problems tied to material structure, properties, selection, failure, and testing, then widens toward independent work. Later courses in the department will assume familiarity with material structure, properties, selection, failure, and testing.', ARRAY[11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '884b0470-d683-49be-8699-cade9f434f48', 'a2b22222-0000-4000-a000-000000000010', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('ad1efd7b-92ef-401f-9442-74604bdee9ac', 'Robotics Engineering', 'Mechanical design, electronics, controls, fabrication, and team competition.', 'Students spend most of class deeply engaged with mechanical design, electronics, controls, fabrication, and team competition, moving between explanation, practice, and critique. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about mechanical design, electronics, controls, fabrication, and team competition under modest time pressure.', ARRAY[9,10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', '1e0c720e-d439-42ac-8964-df7b1578126b', 'a2b22222-0000-4000-a000-000000000010', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('8c74bdf8-813f-488b-b099-f4a93db7d382', 'Principles of Engineering', 'Builds from fundamentals of mechanics, energy, systems, materials, controls, and design analysis.', 'Materials range from classic sources to current tools, all oriented around mechanics, energy, systems, materials, controls, and design analysis. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about mechanics, energy, systems, materials, controls, and design analysis under modest time pressure.', ARRAY[10,11,12], '', 'Engineering', 'a2b20000-0000-4000-a000-000000000000', 'ed80b438-dd5f-4649-8a04-ed6f8856ba5d', 'a2b22222-0000-4000-a000-000000000010', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('c17ef994-432b-40ac-a1fe-bf34babaee61', 'String Orchestra', 'Skills and concepts in orchestral strings, ensemble balance, technique, interpretation, and performance.', 'Students who enroll should be ready for sustained attention to orchestral strings, ensemble balance, technique, interpretation, and performance and for revising unfinished work. Collaborative days alternate with quiet independent stretches so everyone gets both voices and focus time. A final project or exam asks students to integrate what they learned about orchestral strings, ensemble balance, technique, interpretation, and performance under modest time pressure.', ARRAY[9,10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '2f1668f3-4605-4be7-a39c-89680320f7bd', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 36, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('1745de8c-d5cf-4eb2-b438-33234c1d4205', 'Songwriting', 'Performance-centered study of lyrics, melody, harmony, arrangement, demo production, and peer feedback.', 'Early assessments check fluency; later ones ask students to combine ideas related to lyrics, melody, harmony, arrangement, demo production, and peer feedback. The teacher conferences mid-term to adjust challenge level without watering down standards. By the end, students should explain key ideas in lyrics, melody, harmony, arrangement, demo production, and peer feedback clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '163a989e-cb70-4bbf-beae-0d8d41338599', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('a808ae1e-6bde-4549-bcd6-e099cb275f4c', 'Music Theory', 'Hands-on experience with notation, harmony, ear training, analysis, and composition.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into notation, harmony, ear training, analysis, and composition, others synthesize. Portfolios and rehearsal notes become the lasting record of progress with notation, harmony, ear training, analysis, and composition.', ARRAY[10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '35c323db-5696-4af2-be41-b0830511c27f', 'a2b22222-0000-4000-a000-000000000011', false, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('7af41a15-ecaa-468b-bf6f-486017ecd3df', 'AP Music Theory', 'For students ready to take on college-level harmony, part writing, aural skills, analysis, and sight-singing.', 'Field-adjacent examples keep college-level harmony, part writing, aural skills, analysis, and sight-singing connected to situations students recognize outside school. The teacher conferences mid-term to adjust challenge level without watering down standards. A final project or exam asks students to integrate what they learned about college-level harmony, part writing, aural skills, analysis, and sight-singing under modest time pressure.', ARRAY[11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '61558615-4e9f-4494-910a-18e2b590476c', 'a2b22222-0000-4000-a000-000000000011', false, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('13c0739a-3800-4dec-8c51-5a7b03bd9618', 'Jazz Ensemble', 'Term work on improvisation, swing, ensemble style, transcription, and performance.', 'Materials range from classic sources to current tools, all oriented around improvisation, swing, ensemble style, transcription, and performance. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Students finish able to describe artistic choices related to improvisation, swing, ensemble style, transcription, and performance with specific language.', ARRAY[10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', 'a619665e-8f9a-4e43-9d1f-9b07f14f0c93', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('68396439-87b5-4873-8e23-79f604e1fdc7', 'Music Production', 'An elective built around recording, editing, mixing, acoustics, arrangement, and studio workflow.', 'Students spend most of class deeply engaged with recording, editing, mixing, acoustics, arrangement, and studio workflow, moving between explanation, practice, and critique. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. Portfolios and rehearsal notes become the lasting record of progress with recording, editing, mixing, acoustics, arrangement, and studio workflow.', ARRAY[10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '892df09a-2bc8-4372-9b47-79a463b642a9', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('deb6e88e-4336-40b2-868a-914d5a8dfc94', 'Concert Choir', 'A practical look at ensemble singing, vocal technique, sight-reading, and varied choral repertoire.', 'What looks like a narrow topic—ensemble singing, vocal technique, sight-reading, and varied choral repertoire—becomes a route into bigger questions about evidence and craft. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. By the end, students should explain key ideas in ensemble singing, vocal technique, sight-reading, and varied choral repertoire clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '45e234b2-ce62-4630-96f6-f9222a7186ae', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('7feb4f92-b291-451f-993c-0008b5a36e08', 'Concert Choir', 'A practical look at ensemble singing, vocal technique, sight-reading, and varied choral repertoire.', 'What looks like a narrow topic—ensemble singing, vocal technique, sight-reading, and varied choral repertoire—becomes a route into bigger questions about evidence and craft. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. By the end, students should explain key ideas in ensemble singing, vocal technique, sight-reading, and varied choral repertoire clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '45e234b2-ce62-4630-96f6-f9222a7186ae', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('88be62de-c3e9-40ee-a43d-47daf9c0b947', 'Concert Choir', 'A practical look at ensemble singing, vocal technique, sight-reading, and varied choral repertoire.', 'What looks like a narrow topic—ensemble singing, vocal technique, sight-reading, and varied choral repertoire—becomes a route into bigger questions about evidence and craft. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. By the end, students should explain key ideas in ensemble singing, vocal technique, sight-reading, and varied choral repertoire clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '45e234b2-ce62-4630-96f6-f9222a7186ae', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('8cfa160e-6489-497d-8a77-100824c10251', 'Concert Band', 'A practical look at wind ensemble performance, tone, musicianship, rehearsal, and concert repertoire.', 'Materials range from classic sources to current tools, all oriented around wind ensemble performance, tone, musicianship, rehearsal, and concert repertoire. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about wind ensemble performance, tone, musicianship, rehearsal, and concert repertoire under modest time pressure.', ARRAY[9,10,11,12], '', 'Music', 'a2b20000-0000-4000-a000-000000000000', '2184f116-c802-495b-8a2c-ab6aad445581', 'a2b22222-0000-4000-a000-000000000011', true, NULL, NULL, 36, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('087c241d-868a-4e40-971e-c01f4e99370c', 'Musical Theater', 'Practice with integrated acting, singing, movement, audition skills, and performance.', 'Rather than racing through a checklist, the class returns repeatedly to integrated acting, singing, movement, audition skills, and performance until ideas feel usable. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Students finish able to describe artistic choices related to integrated acting, singing, movement, audition skills, and performance with specific language.', ARRAY[10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', 'f36a2148-67d5-4a12-8cc4-2dbdae14d3a9', 'a2b22222-0000-4000-a000-000000000012', true, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77','9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('0398374b-fe06-4c48-a47e-75d0c68a588c', 'Directing', 'Emphasis on script interpretation, staging, actor communication, rehearsal planning, and leadership.', 'Early assessments check fluency; later ones ask students to combine ideas related to script interpretation, staging, actor communication, rehearsal planning, and leadership. Group roles rotate so no one is permanently the scribe or the spokesperson. By the end, students should explain key ideas in script interpretation, staging, actor communication, rehearsal planning, and leadership clearly and apply them without a scripted worksheet.', ARRAY[11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', 'cbb631a6-5f82-426f-a50b-c18d3e317d51', 'a2b22222-0000-4000-a000-000000000012', false, ARRAY[ARRAY['Successful completion of a placement exam','Counselor recommendation']], NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('f1c9e6d5-f547-437a-8592-b4b86ee6c195', 'Acting Studio', 'Seminar and studio approaches to character, objective, voice, movement, scene study, and rehearsal discipline.', 'Teachers model professional habits while students pursue character, objective, voice, movement, scene study, and rehearsal discipline in pairs and on their own. The teacher conferences mid-term to adjust challenge level without watering down standards. A final project or exam asks students to integrate what they learned about character, objective, voice, movement, scene study, and rehearsal discipline under modest time pressure.', ARRAY[10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', 'c34cf6e0-ea55-4b50-b0a2-080341875b82', 'a2b22222-0000-4000-a000-000000000012', true, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 18, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('32179c80-feb8-4b5d-a7a5-694ee470f40d', 'Theater Arts I', 'Core work includes acting foundations, ensemble practice, script analysis, and stage vocabulary.', 'Students spend most of class deeply engaged with acting foundations, ensemble practice, script analysis, and stage vocabulary, moving between explanation, practice, and critique. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. A final project or exam asks students to integrate what they learned about acting foundations, ensemble practice, script analysis, and stage vocabulary under modest time pressure.', ARRAY[9,10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', '42363046-8c44-4cdb-bd2b-484e1bdbe18d', 'a2b22222-0000-4000-a000-000000000012', true, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002']::uuid[]),
('b406bd69-8ccc-4e3f-bef1-84c3fbce4866', 'Playwriting', 'Skills and concepts in dramatic structure, dialogue, character, workshop feedback, and revision.', 'Field-adjacent examples keep dramatic structure, dialogue, character, workshop feedback, and revision connected to situations students recognize outside school. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A public or classroom showcase makes student work on dramatic structure, dialogue, character, workshop feedback, and revision visible beyond the studio.', ARRAY[10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', '70f57023-951a-49dd-acfc-553c2a1201a7', 'a2b22222-0000-4000-a000-000000000012', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('d0ecc337-4803-4257-8a4e-f11d8cb067c5', 'Theater Production', 'Core work includes full-production rehearsal, design collaboration, stage management, and public performance.', 'Field-adjacent examples keep full-production rehearsal, design collaboration, stage management, and public performance connected to situations students recognize outside school. Support structures include office hours, peer tutors, and optional extension problems for those who want more. By the end, students should explain key ideas in full-production rehearsal, design collaboration, stage management, and public performance clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', '4967949b-0b6a-4a02-be9b-79166fcd23b6', 'a2b22222-0000-4000-a000-000000000012', true, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('e2cc0b90-c8e6-4dc3-9cc2-b78a4015bff8', 'Technical Theater', 'For students ready to take on scenery, lighting, sound, costumes, safety, and production teamwork.', 'Studio / rehearsal time dominates; reflection journals document decisions related to scenery, lighting, sound, costumes, safety, and production teamwork. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about scenery, lighting, sound, costumes, safety, and production teamwork under modest time pressure.', ARRAY[9,10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', 'e1d95d2d-5eaf-4f74-b50a-b8e90ee0a0df', 'a2b22222-0000-4000-a000-000000000012', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('0ed273d0-7697-4e40-b049-2ec7346e2885', 'Technical Theater', 'For students ready to take on scenery, lighting, sound, costumes, safety, and production teamwork.', 'Studio / rehearsal time dominates; reflection journals document decisions related to scenery, lighting, sound, costumes, safety, and production teamwork. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about scenery, lighting, sound, costumes, safety, and production teamwork under modest time pressure.', ARRAY[9,10,11,12], '', 'Theater', 'a2b20000-0000-4000-a000-000000000000', 'e1d95d2d-5eaf-4f74-b50a-b8e90ee0a0df', 'a2b22222-0000-4000-a000-000000000012', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('258fdbd9-0f6e-43e0-8fa5-82db878a25ec', 'Entrepreneurship', 'Attention to opportunity discovery, customer research, business models, pitching, and iteration.', 'Students who enroll should be ready for sustained attention to opportunity discovery, customer research, business models, pitching, and iteration and for revising unfinished work. Reading loads stay manageable; the heavier lift is interpreting and producing original work. By the end, students should explain key ideas in opportunity discovery, customer research, business models, pitching, and iteration clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '6732e5bf-ffbf-4cbe-b72f-e94f89aca914', 'a2b22222-0000-4000-a000-000000000013', true, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]),
('52edb6a0-fa94-49ca-93d9-3a51ff07aac9', 'Introduction to Business', 'Builds from fundamentals of business functions, ownership, markets, operations, and workplace decision making.', 'Materials range from classic sources to current tools, all oriented around business functions, ownership, markets, operations, and workplace decision making. Rubrics privilege clarity of reasoning over mere length; incomplete but thoughtful drafts can still score well. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '4cba98cd-d442-41d2-bb41-553eebf9b2d4', 'a2b22222-0000-4000-a000-000000000013', false, NULL, ARRAY[ARRAY['Concurrent enrollment in a math course']], 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('120381ec-ac4b-4040-b707-0e6516c27596', 'Business Law', 'Emphasis on contracts, employment, consumer protection, business ethics, and legal reasoning.', 'This offering is sequenced for the grades it serves, with contracts, employment, consumer protection, business ethics, and legal reasoning as the spine of major assignments. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about contracts, employment, consumer protection, business ethics, and legal reasoning under modest time pressure.', ARRAY[11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '92ea76ab-03a1-4376-be93-9c7a2530304d', 'a2b22222-0000-4000-a000-000000000013', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('1844a4c2-563d-46e6-883e-d0776995bc7c', 'Accounting I', 'An elective built around financial statements, transactions, ledgers, controls, and business reporting.', 'Rather than racing through a checklist, the class returns repeatedly to financial statements, transactions, ledgers, controls, and business reporting until ideas feel usable. Homework is modest but cumulative; missing a few days is noticeable on the next checkpoint. Later courses in the department will assume familiarity with financial statements, transactions, ledgers, controls, and business reporting.', ARRAY[10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '21e6b71d-abc0-4e56-8125-185d0d65052f', 'a2b22222-0000-4000-a000-000000000013', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('c7bc965b-e1ca-4829-915b-5d45f299d701', 'Marketing', 'Practice with audience research, positioning, brand strategy, promotion, and campaign measurement.', 'Guest voices (recordings, articles, or local practitioners) periodically reframe how audience research, positioning, brand strategy, promotion, and campaign measurement is used. Group roles rotate so no one is permanently the scribe or the spokesperson.', ARRAY[10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '9742ee63-043d-4d8b-b5a9-8c6efe1eb19a', 'a2b22222-0000-4000-a000-000000000013', false, ARRAY[ARRAY['9352533d-9b5c-49ea-8426-6d64b653827e'], ARRAY['Teacher recommendation']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('0b60ffef-5ca5-432a-b9e3-1ae9a88ad085', 'Personal Finance', 'A practical look at budgeting, credit, taxes, insurance, investing, and financial decision making.', 'What looks like a narrow topic—budgeting, credit, taxes, insurance, investing, and financial decision making—becomes a route into bigger questions about evidence and craft. By the end, students should explain key ideas in budgeting, credit, taxes, insurance, investing, and financial decision making clearly and apply them without a scripted worksheet.', ARRAY[10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', '062b677c-17e3-4f93-8684-c2dfc466f3b9', 'a2b22222-0000-4000-a000-000000000013', false, ARRAY[ARRAY['8e95568c-ab36-48c7-9435-2b75320cd454']], NULL, 30, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('21db42e2-6aa6-4f10-b78f-f420ccc972c5', 'Sports and Entertainment Management', 'Core work includes events, sponsorship, budgeting, promotion, operations, and audience experience.', 'Teachers model professional habits while students pursue events, sponsorship, budgeting, promotion, operations, and audience experience in pairs and on their own. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[10,11,12], '', 'Business', 'a2b20000-0000-4000-a000-000000000000', 'c482ee0f-1a4c-4769-8df0-a1c8bf3f49e0', 'a2b22222-0000-4000-a000-000000000013', true, ARRAY[ARRAY['a9541047-4970-45a2-a979-70d58f9b8909']], NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('47864a3c-69e9-47f9-b5f0-c7f239effd9f', 'Media Literacy', 'Covers source evaluation, representation, algorithms, persuasion, and responsible participation.', 'The term opens with concrete problems tied to source evaluation, representation, algorithms, persuasion, and responsible participation, then widens toward independent work. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'Media Studies', 'a2b20000-0000-4000-a000-000000000000', 'ed83a617-b482-4f75-994c-2711dda69c16', 'a2b22222-0000-4000-a000-000000000014', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('f406e4db-a57f-41d5-abfb-89e48d7bddd3', 'Documentary Production', 'Skills and concepts in nonfiction research, ethics, cinematography, editing, and public screening.', 'Field-adjacent examples keep nonfiction research, ethics, cinematography, editing, and public screening connected to situations students recognize outside school. The teacher conferences mid-term to adjust challenge level without watering down standards. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[11,12], '', 'Media Studies', 'a2b20000-0000-4000-a000-000000000000', 'f62c28e2-f5ee-4e8d-90c5-0746a249f149', 'a2b22222-0000-4000-a000-000000000014', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9c9d9bd4-a1b6-4126-a16c-b1f1d50e22af', 'Film Studies', 'An elective built around film language, genre, history, criticism, and cultural interpretation.', 'Rather than racing through a checklist, the class returns repeatedly to film language, genre, history, criticism, and cultural interpretation until ideas feel usable. Reading loads stay manageable; the heavier lift is interpreting and producing original work. A final project or exam asks students to integrate what they learned about film language, genre, history, criticism, and cultural interpretation under modest time pressure.', ARRAY[10,11,12], '', 'Media Studies', 'a2b20000-0000-4000-a000-000000000000', '1539b9fb-4f7c-485f-834c-f1ba4fdb8c2f', 'a2b22222-0000-4000-a000-000000000014', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('522f4896-cf05-4357-8b31-3d0ebf012fe9', 'Podcasting and Audio Storytelling', 'Seminar and studio approaches to reporting, scripting, interviewing, sound design, editing, and distribution.', 'Workshops, mini-lectures, and critiques rotate so that reporting, scripting, interviewing, sound design, editing, and distribution never stays only on a worksheet. Optional enrichment is posted weekly for students aiming at contests, auditions, or portfolios. A final project or exam asks students to integrate what they learned about reporting, scripting, interviewing, sound design, editing, and distribution under modest time pressure.', ARRAY[10,11,12], '', 'Media Studies', 'a2b20000-0000-4000-a000-000000000000', 'f6af7c7c-3b74-46b9-bf1d-30c294dbceb7', 'a2b22222-0000-4000-a000-000000000014', true, ARRAY[ARRAY['a39e0f13-b896-458e-8ecc-0753668fbc77']], ARRAY[ARRAY['Ability to meet publication deadlines']], 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('4f8cd2df-7c0e-4aaa-b0f8-6d3b282277ca', 'Philosophy of Mind', 'Skills and concepts in consciousness, identity, perception, artificial intelligence, and personal agency.', 'Field-adjacent examples keep consciousness, identity, perception, artificial intelligence, and personal agency connected to situations students recognize outside school. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Later courses in the department will assume familiarity with consciousness, identity, perception, artificial intelligence, and personal agency.', ARRAY[11,12], '', 'Philosophy', 'a2b20000-0000-4000-a000-000000000000', 'c7168d9b-e8a8-4cd7-9347-684e205434e5', 'a2b22222-0000-4000-a000-000000000015', false, ARRAY[ARRAY['7f077bc3-e89d-40b5-9ecd-6d87ebfb27d7']], NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('0827ceb1-51e3-445b-b19a-c99a2645ee03', 'Political Philosophy', 'Hands-on experience with justice, liberty, equality, authority, rights, and civic obligation.', 'The syllabus is deliberately uneven in pace—some weeks dig deep into justice, liberty, equality, authority, rights, and civic obligation, others synthesize. The teacher conferences mid-term to adjust challenge level without watering down standards. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[11,12], '', 'Philosophy', 'a2b20000-0000-4000-a000-000000000000', 'b806b378-3c0a-4e55-8035-a2916b1215db', 'a2b22222-0000-4000-a000-000000000015', false, NULL, ARRAY[ARRAY['9b8ade0d-4069-4740-84a4-958ad890c229']], 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('d2570fcd-b773-48a2-b6fb-e5555dde194e', 'Introduction to Philosophy', 'Lab- and project-driven work on fundamental questions, argument analysis, close reading, and philosophical dialogue.', 'Expect a mix of short drills and longer investigations organized around fundamental questions, argument analysis, close reading, and philosophical dialogue. Later courses in the department will assume familiarity with fundamental questions, argument analysis, close reading, and philosophical dialogue.', ARRAY[10,11,12], '', 'Philosophy', 'a2b20000-0000-4000-a000-000000000000', '3a4db3fb-3005-4f0e-8ee7-75ac3ecff665', 'a2b22222-0000-4000-a000-000000000015', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('bdbe4561-70b4-4097-8ba1-a0c22e95379a', 'Logic and Critical Thinking', 'Attention to argument structure, validity, fallacies, evidence, and precise reasoning.', 'Students who enroll should be ready for sustained attention to argument structure, validity, fallacies, evidence, and precise reasoning and for revising unfinished work. Reading loads stay manageable; the heavier lift is interpreting and producing original work. By the end, students should explain key ideas in argument structure, validity, fallacies, evidence, and precise reasoning clearly and apply them without a scripted worksheet.', ARRAY[9,10,11,12], '', 'Philosophy', 'a2b20000-0000-4000-a000-000000000000', 'd3b786aa-8557-4b17-bd93-1d94a66af4f6', 'a2b22222-0000-4000-a000-000000000015', false, NULL, NULL, 24, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('fd5b8d06-d51e-4a99-81bf-95c22a36fd39', 'Ethics', 'Lab- and project-driven work on moral theories, applied dilemmas, reasoned judgment, and respectful disagreement.', 'Expect a mix of short drills and longer investigations organized around moral theories, applied dilemmas, reasoned judgment, and respectful disagreement. Group roles rotate so no one is permanently the scribe or the spokesperson. A final project or exam asks students to integrate what they learned about moral theories, applied dilemmas, reasoned judgment, and respectful disagreement under modest time pressure.', ARRAY[10,11,12], '', 'Philosophy', 'a2b20000-0000-4000-a000-000000000000', '9b06de25-6945-4379-a10c-94902424d4cd', 'a2b22222-0000-4000-a000-000000000015', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('4af3b798-b6da-4be3-b24d-e2d9694211cc', 'First Aid and CPR', 'For students ready to take on emergency assessment, injury response, CPR, AED use, and prevention.', 'Discussion norms matter here: peers must press on each other''s reasoning about emergency assessment, injury response, CPR, AED use, and prevention. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. The last stretch of the term prioritizes revision over packing in brand-new material.', ARRAY[9,10,11,12], '', 'Health', 'a2b20000-0000-4000-a000-000000000000', '784aabef-d9af-4ea4-a75c-de954f4299b1', 'a2b22222-0000-4000-a000-000000000016', true, NULL, NULL, 18, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('6d1bcf7d-2e92-4c0e-a15d-82be4e538b84', 'Mental Health and Wellbeing', 'Emphasis on stress, resilience, relationships, help-seeking, and stigma reduction.', 'This offering is sequenced for the grades it serves, with stress, resilience, relationships, help-seeking, and stigma reduction as the spine of major assignments. Technology is used when it clarifies ideas, not as decoration—paper notebooks still matter. A final project or exam asks students to integrate what they learned about stress, resilience, relationships, help-seeking, and stigma reduction under modest time pressure.', ARRAY[10,11,12], '', 'Health', 'a2b20000-0000-4000-a000-000000000000', '576c6d64-38f5-42ab-9068-7a9fcb5f70ef', 'a2b22222-0000-4000-a000-000000000016', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000001']::uuid[]),
('4b742615-bef6-4da8-9f83-391ce95613e4', 'Public Health', 'For students ready to take on population health, prevention, disparities, epidemiology, and community intervention.', 'Discussion norms matter here: peers must press on each other''s reasoning about population health, prevention, disparities, epidemiology, and community intervention. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. A final project or exam asks students to integrate what they learned about population health, prevention, disparities, epidemiology, and community intervention under modest time pressure.', ARRAY[11,12], '', 'Health', 'a2b20000-0000-4000-a000-000000000000', '7241ef30-aa09-462a-845b-5fd7be4617c4', 'a2b22222-0000-4000-a000-000000000016', false, NULL, NULL, 22, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('9ec7bcd2-15ec-4d77-b7f9-81b75e317d59', 'Health Education', 'A practical look at physical, mental, social, and community dimensions of lifelong wellness.', 'What looks like a narrow topic—physical, mental, social, and community dimensions of lifelong wellness—becomes a route into bigger questions about evidence and craft. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Students leave with notes and graded work that document progress on physical, mental, social, and community dimensions of lifelong wellness.', ARRAY[9], '', 'Health', 'a2b20000-0000-4000-a000-000000000000', '53dba946-21aa-4345-922c-f07e8343229b', 'a2b22222-0000-4000-a000-000000000016', false, NULL, NULL, 28, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('18de3a75-496b-47fc-802e-e1774ebaceff', 'Nutrition and Wellness', 'Seminar and studio approaches to nutrients, food systems, energy balance, habits, and evidence-based choices.', 'Workshops, mini-lectures, and critiques rotate so that nutrients, food systems, energy balance, habits, and evidence-based choices never stays only on a worksheet. The teacher conferences mid-term to adjust challenge level without watering down standards. Later courses in the department will assume familiarity with nutrients, food systems, energy balance, habits, and evidence-based choices.', ARRAY[9,10,11,12], '', 'Health', 'a2b20000-0000-4000-a000-000000000000', '366b9f26-5a40-4050-9afc-e8cac7ab0b85', 'a2b22222-0000-4000-a000-000000000016', false, NULL, NULL, 26, ARRAY['a2b21111-0000-4000-a000-000000000003','a2b21111-0000-4000-a000-000000000004']::uuid[]),
('235215dd-7078-4fb3-b0ec-2a4a1f4c84d0', 'Public Forum Debate', 'Skills and concepts in current-events research, concise advocacy, teamwork, and audience adaptation.', 'Field-adjacent examples keep current-events research, concise advocacy, teamwork, and audience adaptation connected to situations students recognize outside school. Assessments mix short quizzes with performance tasks that look more like real work than trap questions. Later courses in the department will assume familiarity with current-events research, concise advocacy, teamwork, and audience adaptation.', ARRAY[9,10,11,12], '', 'Debate', 'a2b20000-0000-4000-a000-000000000000', '26cf77e5-f4c5-49ea-8ee0-7854fe3ac884', 'a2b22222-0000-4000-a000-000000000017', true, ARRAY[ARRAY['48f02bd3-bf5f-4b58-b052-74771c89b413']], ARRAY[ARRAY['f7c7b4e6-c7eb-4a97-a7f5-c5e591e716fe']], 18, ARRAY['a2b21111-0000-4000-a000-000000000002']::uuid[]),
('386cf578-edaf-40ec-9ff9-cb17b45913be', 'Speech and Debate Team', 'Skills and concepts in competitive speaking events, debate preparation, peer coaching, and tournament reflection.', 'Field-adjacent examples keep competitive speaking events, debate preparation, peer coaching, and tournament reflection connected to situations students recognize outside school. Cross-course connections (when schedules allow) show how the same idea travels across disciplines. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[9,10,11,12], '', 'Debate', 'a2b20000-0000-4000-a000-000000000000', '60a114ee-13cd-4c3a-80e9-bcfe09c5533e', 'a2b22222-0000-4000-a000-000000000017', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000001','a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('e09011be-04a4-486e-aac1-844117096c7d', 'Introduction to Debate', 'Covers claim construction, evidence, refutation, delivery, and tournament formats.', 'The term opens with concrete problems tied to claim construction, evidence, refutation, delivery, and tournament formats, then widens toward independent work. Later courses in the department will assume familiarity with claim construction, evidence, refutation, delivery, and tournament formats.', ARRAY[9,10,11,12], '', 'Debate', 'a2b20000-0000-4000-a000-000000000000', 'cb011d9b-aa82-4608-9cbf-22d0ccea0f55', 'a2b22222-0000-4000-a000-000000000017', true, NULL, NULL, 20, ARRAY['a2b21111-0000-4000-a000-000000000002','a2b21111-0000-4000-a000-000000000003']::uuid[]),
('eae55d07-2c41-44c6-b177-119f4f7e0a47', 'Policy Debate', 'Attention to policy research, case construction, cross-examination, strategy, and competition.', 'Students who enroll should be ready for sustained attention to policy research, case construction, cross-examination, strategy, and competition and for revising unfinished work. Support structures include office hours, peer tutors, and optional extension problems for those who want more. Credit depends on both the summative assessment and consistent participation during class meetings.', ARRAY[10,11,12], '', 'Debate', 'a2b20000-0000-4000-a000-000000000000', 'c9068536-0f69-4476-8d6b-1d098295bde9', 'a2b22222-0000-4000-a000-000000000017', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000004']::uuid[]),
('58115363-3198-4528-8f51-50c6fdc0b169', 'Lincoln-Douglas Debate', 'Lab- and project-driven work on value conflict, philosophical frameworks, evidence, refutation, and competition.', 'Expect a mix of short drills and longer investigations organized around value conflict, philosophical frameworks, evidence, refutation, and competition. Students leave with notes and graded work that document progress on value conflict, philosophical frameworks, evidence, refutation, and competition.', ARRAY[10,11,12], '', 'Debate', 'a2b20000-0000-4000-a000-000000000000', 'd038eecf-4fc0-4b59-86ab-86d9a32e588c', 'a2b22222-0000-4000-a000-000000000017', true, NULL, NULL, 16, ARRAY['a2b21111-0000-4000-a000-000000000003']::uuid[]);

